Object.assign(window.TEM8_DICTIONARY, {"brown":{"media":{"uk":"media/uk/brown__gb_1.mp3","us":"media/us/brown__us_1.mp3"},"oxford":{"phon":"braʊn","pos":"adjective","senses":[{"en":"having the colour of earth or coffee","cn":"棕色的；褐色的","ex":{"en":"brown eyes/hair","cn":"褐色的眼睛／头发"}},{"en":"having skin that is naturally brown or has been made brown by the sun","cn":"（皮肤）棕色的，被晒黑的","lab":"British English","ex":{"en":"I don't go brown very easily.","cn":"我不容易晒黑。"}},{"en":"the colour of earth or coffee","cn":"棕色；褐色","ex":{"en":"leaves of various shades of brown","cn":"深浅不一的棕色叶子"},"pos":"noun"},{"en":"to become brown; to make something brown","cn":"（使）变成棕色；成褐色","ex":{"en":"Heat the butter until it browns.","cn":"把黄油加热，使之呈棕色。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"COLOUR 颜色词","cn":"褐色；棕色","en":"Something that is brown is the colour of earth or of wood.","ex":{"en":"...her deep brown eyes","cn":"她深褐色的眼睛"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"皮肤晒成棕色的；皮肤晒黑的","en":"You can describe a white-skinned person as brown when they have been sitting in the sun until their skin has become darker than usual.","ex":{"en":"I don't want to be really really brown, just have a nice light golden colour.","cn":"我不想晒得黝黑，只想晒成一种漂亮的淡金色。"}},{"pos":"VERB 动词","cn":"晒黑","en":"If someone browns in the sun they become brown in colour.","ex":{"en":"Her skin was of the fortunate kind that could brown in the sun without burning","cn":"她的皮肤属于那种很幸运的类型，在阳光下无需长时间晒着就能变黑。"}},{"pos":"ADJ 形容词","cn":"棕种人的；棕色皮肤的","en":"A brown person is someone who belongs to a race of people who have brown-coloured skins.","ex":{"en":"...a slim brown man with a speckled turban.","cn":"一个戴着花头巾、身材瘦削、棕色皮肤的男子"}},{"pos":"ADJ-UNGRADED 形容词","cn":"（谷物）未去壳的，糙的","en":"Brown is used to describe grains that have not had their outer layers removed, and foods made from these grains.","ex":{"en":"...brown bread.","cn":"黑面包"}},{"pos":"V-ERG 及物/不及物动词","cn":"（用旺火把)(食物)烤得焦黄；（把…）炸成焦黄色","en":"When food browns or when you brown food, you cook it, usually for a short time on a high flame.","ex":{"en":"Cook for ten minutes until the sugar browns","cn":"熬煮10分钟，直到糖变成褐色。"}}]},"examples":[{"en":"After the summer in Spain, the children were brown as berries.","cn":"在西班牙度过了一个夏天之后，孩子们被晒得黝黑。"},{"en":"By now the passengers were getting browned off with the delay.","cn":"此时乘客们对延误已开始感到不满。"}]},"brought":{"lemma":"bring","media":{"uk":"media/uk/brought__gb_1.mp3","us":"media/us/brought__us_1.mp3"}},"bridge":{"media":{"img":["media/ldoce/img/bridge.jpg","media/pic/bridge_senses.jpg"],"uk":"media/uk/bridge__gb_1.mp3","us":"media/us/bridge__us_1.mp3"},"oxford":{"phon":"brɪdʒ","pos":"noun","senses":[{"en":"a structure that is built over a road, railway, river, etc. so that people, vehicles, etc. can cross from one side to the other","cn":"桥","g":"[countable]","sc":"over road/river","ex":{"en":"We crossed the bridge over the River Windrush.","cn":"我们通过了温德拉什河上的桥。"}},{"en":"a thing that provides a connection or contact between two different things","cn":"起联系作用的事物；桥梁；纽带","g":"[countable]","sc":"connection","ex":{"en":"The book serves as a bridge between ancient wisdom and modern science.","cn":"这本书是古代智慧和现代科学之间的桥梁。"}},{"en":"the part of a ship where the captain and other officers stand when they are controlling the ship","cn":"（舰船的）驾驶台；船桥；舰桥","g":"[countable, usually singular]","sc":"of ship","ex":{"en":"Who was on the bridge when the collision took place?","cn":"碰撞发生时谁在桥上？"}},{"en":"a card game for two pairs of players who have to predict how many cards they will win. They score points if they succeed in winning that number of cards and lose points if they fail.","cn":"桥牌","g":"[uncountable]","sc":"card game","ex":{"en":"I enjoy a game of bridge occasionally.","cn":"我偶尔也玩桥牌。"}},{"en":"the hard part at the top of the nose, between the eyes","cn":"鼻梁","g":"[singular]","sc":"of nose"},{"en":"the part of a pair of glasses that rests on your nose","cn":"鼻梁架","g":"[countable]","sc":"of glasses"},{"en":"a small piece of wood on a guitar, violin, etc. over which the strings are stretched","cn":"琴马","g":"[countable]","sc":"of guitar/violin"},{"en":"a false tooth or false teeth, held permanently in place by being fastened to natural teeth on either side","cn":"（固定的）假牙；齿桥","g":"[countable]","sc":"false teeth"},{"en":"to build or form a bridge over something","cn":"在…上架桥","sc":"build/form bridge","ex":{"en":"The valley was originally bridged by the Romans.","cn":"那条峡谷上的桥最初是古罗马人修建的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"桥；桥梁","en":"A bridge is a structure that is built over a railway, river, or road so that people or vehicles can cross from one side to the other.","ex":{"en":"He walked back over the railway bridge.","cn":"他从铁路桥上走了回去。"}},{"pos":"N-COUNT 可数名词","cn":"（连接两地的）桥梁，纽带","en":"A bridge between two places is a piece of land that joins or connects them.","ex":{"en":"...a land bridge linking Serbian territories.","cn":"连接塞尔维亚不同地区的陆桥"}},{"pos":"VERB 动词","cn":"弥合（分歧）；消除（隔阂）","en":"To bridge the gap between two people or things means to reduce it or get rid of it.","ex":{"en":"It is unlikely that the two sides will be able to bridge their differences.","cn":"双方不太可能消除彼此之间的分歧。"}},{"pos":"VERB 动词","cn":"兼具… 的特点","en":"Something that bridges the gap between two very different things has some of the qualities of each of these things.","ex":{"en":"...the singer who bridged the gap between pop music and opera.","cn":"将通俗音乐与歌剧结合起来的歌手"}},{"pos":"N-COUNT 可数名词","cn":"桥梁；媒介；纽带","en":"If something or someone acts as a bridge between two people, groups, or things, they connect them.","ex":{"en":"We hope this book will act as a bridge between doctor and patient","cn":"我们希望这本书能成为医生与患者之间沟通的桥梁。"}},{"pos":"N-COUNT 可数名词","cn":"舰桥","en":"The bridge is the place on a ship from which it is steered."},{"pos":"N-COUNT 可数名词","cn":"鼻梁","en":"The bridge of your nose is the thin top part of it, between your eyes.","ex":{"en":"On the bridge of his hooked nose was a pair of gold rimless spectacles.","cn":"他的鹰钩鼻上架着一副金色无框眼镜。"}},{"pos":"N-COUNT 可数名词","cn":"（眼镜的）鼻梁架","en":"The bridge of a pair of glasses is the part that rests on your nose."},{"pos":"N-COUNT 可数名词","cn":"（小提琴、吉他等弦乐器的）琴马，琴桥","en":"The bridge of a violin, guitar, or other stringed instrument is the small piece of wood under the strings that holds them up."},{"pos":"N-COUNT 可数名词","cn":"（固定假牙的）齿桥","en":"A bridge is a piece of metal or plastic that holds false teeth in place by connecting them to natural teeth."},{"pos":"N-UNCOUNT 不可数名词","cn":"桥牌","en":"Bridge is a card game for four players in which the players begin by declaring how many tricks they expect to win."},{"pos":"PHRASE 短语","cn":"破釜沉舟；自绝退路","en":"If you burn your bridges, you do something which forces you to continue with a particular course of action, and makes it impossible for you to return to an earlier situation or relationship."},{"pos":"","cn":"","en":"water under the bridge→see: ;"}]},"examples":[{"en":"The valley was originally bridged by the Romans.","cn":"那条峡谷上的桥最初是古罗马人修建的。"},{"en":"Cultural exchanges are a way of building bridges between countries.","cn":"文化交流是各国之间建立联系的纽带。"}]},"breathe":{"oxford":{"phon":"briːð","pos":"verb","senses":[{"en":"to take air into your lungs and send it out again through your nose or mouth","cn":"呼吸","g":"[intransitive, transitive]","sc":"air/breath","ex":{"en":"He breathed deeply before speaking again.","cn":"他深深吸一口气，然后继续说下去。"}},{"en":"to send air, smoke or a particular smell out of your mouth","cn":"呼出","g":"[transitive]","lab":"figurative","sc":"air/breath","ex":{"en":"He came up close, breathing alcohol fumes all over me.","cn":"他走过来靠近我，喷得我满身酒气。"}},{"en":"to say something quietly","cn":"低声说","g":"[transitive]","lab":"literary","sc":"say quietly","ex":{"en":"‘I'm over here,’ she breathed.","cn":"“我在这儿呢。”她轻声说。"}},{"en":"if you allow wine to breathe, you open the bottle and let air get in before you drink it","cn":"（打开瓶盖，让酒）通气飘香","g":"[intransitive]","sc":"of wine"},{"en":"if cloth, leather, skin, etc. can breathe, air can move around or through it","cn":"透气","g":"[intransitive]","sc":"of cloth/skin","ex":{"en":"Cotton clothing allows your skin to breathe.","cn":"棉织品能使皮肤透气。"}},{"en":"to be full of a particular feeling or quality","cn":"充满，散发（某种感情或品质）","g":"[transitive]","lab":"formal","sc":"feeling/quality","ex":{"en":"Her performance breathed wit and charm.","cn":"她的表演灵巧迷人。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"呼吸；吸；呼","en":"When people or animals breathe, they take air into their lungs and let it out again. When they breathe smoke or a particular kind of air, they take it into their lungs and let it out again as they breathe.","ex":{"en":"He stood there breathing deeply and evenly","cn":"他站在那儿均匀地深呼吸。"}},{"pos":"VERB 动词","cn":"轻声说出","en":"If someone breathes something, they say it very quietly.","ex":{"en":"'You don't understand,' he breathed.","cn":"“你不明白。”他低声说道。"}},{"pos":"VERB 动词","cn":"吐露；说出","en":"If you do not breathe a word about something, you say nothing about it, because it is a secret.","ex":{"en":"He never breathed a word about our conversation.","cn":"关于我们的谈话他只字未提。"}},{"pos":"VERB 动词","cn":"将（生气、信心或兴奋）注入；为…带来","en":"If someone breathes life, confidence, or excitement into something, they improve it by adding this quality.","ex":{"en":"It is the readers who breathe life into a newspaper with their letters.","cn":"是读者通过来信给报纸带来了生气。"}},{"pos":"VERB 动词","cn":"（酒）通气透香","en":"If you let wine breathe, you open the bottle to allow the air to get in and improve its flavour before you drink it.","ex":{"en":"Red wines should be allowed to 'breathe' if possible before drinking.","cn":"如果可能的话，在饮用红酒前应该先开瓶透透气。"}},{"pos":"PHRASE 短语","cn":"咽气；断气；死去","en":"When someone breathes their last, they die."},{"pos":"","cn":"","en":"to be breathing down someone's neck→see: ; to breathe a sigh of relief→see: ;"},{"pos":"","cn":"","en":"相关词组：breathe in breathe out"}]},"media":{"uk":"media/uk/breathe__gb_1.mp3","us":"media/us/breathe__us_1.mp3"},"examples":[{"en":"Most people don't realize that they are breathing polluted air.","cn":"大多数人没有意识到自己正呼吸着污染了的空气。"},{"en":"He breathed deeply before speaking again.","cn":"他深深吸一口气，然后继续说下去。"}]},"bread":{"media":{"uk":"media/uk/bread__gb_1.mp3","us":"media/us/bread__us_1.mp3","img":["media/ldoce/img/loaf_bread.jpg"]},"oxford":{"phon":"bred","pos":"noun","senses":[{"en":"a type of food made from flour, water and usually yeast mixed together and baked","cn":"面包","ex":{"en":"a loaf/slice/piece of bread","cn":"一条／一片／一块面包"}},{"en":"money","cn":"钱；钞票","lab":"old-fashioned, slang，，"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"面包","en":"Bread is a very common food made from flour, water, and yeast.","ex":{"en":"...a loaf of bread","cn":"一条面包"}},{"pos":"","cn":"","en":"to know what side your bread is buttered on→see: ;"},{"pos":"N-UNCOUNT 不可数名词","cn":"（通过工作等挣得的）钱财，金钱","en":"If you earn your bread doing a particular job or activity, you earn your money doing it.","ex":{"en":"There's not a living soul in Colorado who doesn't depend for his bread on silver.","cn":"科罗拉多的每一个人都是靠着开采银矿养家糊口。"}},{"pos":"VERB 动词","cn":"给（鱼或肉）抹面包屑","en":"If food such as fish or meat is breaded, it is covered in tiny pieces of dry bread called breadcrumbs. It can then be fried or grilled.","ex":{"en":"It is important that food be breaded just minutes before frying.","cn":"把食物抹上面包屑后过几分钟就炸，这一点很重要。"}}]},"examples":[{"en":"a loaf/slice/piece of bread","cn":"一条/一片/一块面包"},{"en":"white/brown/wholemeal bread","cn":"白/黑/全麦面包"}]},"bridegroom":{"oxford":{"phon":"ˈbraɪdɡruːm","pos":"noun","senses":[{"en":"a man on his wedding day, or just before or just after it","cn":"新郎；即将（或刚刚）结婚的男子","ex":{"en":"I enjoyed the bridegroom’s speech.","cn":"我很喜欢新郎的演讲。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"新郎","en":"A bridegroom is a man who is getting married."}]},"media":{"uk":"media/uk/bridegroom__gb_1.mp3","us":"media/us/bridegroom__us_1.mp3"}},"broken":{"media":{"img":["media/ldoce/img/broken.jpg","media/pic/broken_comp.jpg"],"uk":"media/uk/broken__gb_1.mp3","us":"media/us/broken__us_1.mp3"},"oxford":{"phon":"ˈbrəʊkən","pos":"adjective","senses":[{"en":"that has been damaged or injured; no longer whole or working correctly","cn":"破损的；伤残的；残缺的；出了毛病的","sc":"damaged","ex":{"en":"a broken window/plate","cn":"破碎的窗玻璃／盘子"}},{"en":"not kept","cn":"被违背的；未履行的","g":"[usually before noun]","sc":"promise/agreement","ex":{"en":"Voters are disillusioned with the government's broken promises.","cn":"政府言而无信，令选民大失所望。"}},{"en":"ended or destroyed","cn":"终止了的；破坏了的","g":"[usually before noun]","sc":"relationship","ex":{"en":"a broken marriage/engagement","cn":"破裂的婚姻；解除了的婚约"}},{"en":"not continuous; interrupted or disturbed","cn":"不连续的；间断的；被打扰的","g":"[usually before noun]","sc":"not continuous","ex":{"en":"a night of broken sleep","cn":"睡得不踏实的一夜"}},{"en":"made weak and tired by illness or difficulties","cn":"衰弱的；精疲力竭的","g":"[only before noun]","sc":"person","ex":{"en":"He was a broken man after the failure of his business.","cn":"生意失败后他变得心灰意懒。"}},{"en":"spoken slowly and with a lot of mistakes; not fluent","cn":"说得慢且有错的；不流利的","g":"[only before noun]","sc":"language","ex":{"en":"to speak in broken English","cn":"说一口结结巴巴的英语"}},{"en":"having a rough surface","cn":"表面粗糙的","sc":"ground","ex":{"en":"an area of broken, rocky ground","cn":"崎岖、多岩石的地区"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Broken is the past participle of break ."},{"pos":"ADJ 形容词","cn":"（线条）不连贯的，断续的，中断的","en":"A broken line is not continuous but has gaps or spaces in it.","ex":{"en":"A broken blue line means the course of a waterless valley.","cn":"蓝色虚线代表无水流过的山谷。"}},{"pos":"ADJ 形容词","cn":"（婚姻）破裂的","en":"You can use broken to describe a marriage that has ended in divorce, or a home in which the parents of the family are divorced, when you think this is a sad or bad thing.","ex":{"en":"She spoke for the first time about the traumas of a broken marriage","cn":"她首度谈起婚姻破裂带来的精神创伤。"}},{"pos":"ADJ 形容词","cn":"（语言）蹩脚的，不流利的","en":"If someone talks in broken English, for example, or in broken French, they speak slowly and make a lot of mistakes because they do not know the language very well.","ex":{"en":"Eric could only respond in broken English.","cn":"埃里克只能用蹩脚的英语回答。"}}]},"examples":[{"en":"a single broken white line across the road","cn":"横穿马路的一条断断续续的白线"},{"en":"He was a broken man after the failure of his business.","cn":"生意失败后他变得心灰意懒。"}],"base":"break"},"brand":{"media":{"uk":"media/uk/brand__gb_1.mp3","us":"media/us/brand__us_1.mp3"},"oxford":{"phon":"brænd","pos":"noun","senses":[{"en":"a type of product, service, etc. made or offered by a particular company under a particular name","cn":"品牌","lab":"British English","ex":{"en":"a well-known brand of toothpaste","cn":"知名的牙膏品牌"}},{"en":"a particular type or kind of something","cn":"类型","ex":{"en":"an unorthodox brand of humour","cn":"别具一格的幽默"}},{"en":"a mark made with a piece of hot metal, especially on farm animals to show who owns them","cn":"烙印（尤指农场牲畜身上表示所属的印记）"},{"en":"to apply a brand name, image or identity to something","cn":"加商标（或形象、身份等）于","ex":{"en":"The website was not doing a very good job of branding the company.","cn":"该网站在宣传公司品牌方面做得不太好。"},"pos":"verb"},{"en":"to describe somebody/something as being something bad or unpleasant, especially unfairly","cn":"（尤指不公正地）丑化（某人），败坏（某人）名声","ex":{"en":"They were branded as liars and cheats.","cn":"他们被说成是说谎者和骗子。"},"pos":"verb"},{"en":"to mark an animal with a brand to show who owns it","cn":"给（牲畜）打烙印","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"牌子；品牌","en":"A brand of a product is the version of it that is made by one particular manufacturer.","ex":{"en":"Winston is a brand of cigarette","cn":"“温斯顿”是一个香烟品牌。"}},{"pos":"N-COUNT 可数名词","cn":"（思维或行为等的）一种，一类","en":"A brand of something such as a way of thinking or behaving is a particular kind of it.","ex":{"en":"The British brand of socialism was more interested in reform than revolution.","cn":"英国式的社会主义更加注重改革，而不是革命。"}},{"pos":"VERB 动词","cn":"加污名于；谴责","en":"If someone is branded as something bad, people think they are that thing.","ex":{"en":"I was instantly branded as a rebel","cn":"转眼间我被诬蔑为叛徒。"}},{"pos":"VERB 动词","cn":"在（动物）身上打烙印","en":"When you brand an animal, you put a permanent mark on its skin in order to show who it belongs to, usually by burning a mark onto its skin.","ex":{"en":"The owner couldn't be bothered to brand the cattle.","cn":"主人懒得给牛打烙印。"}},{"pos":"N-COUNT 可数名词","cn":"（打在动物身上的）烙印","en":"A brand is a permanent mark on the skin of an animal, which shows who it belongs to."}]},"examples":[{"en":"brand loyalty (= the tendency of customers to continue buying the same brand)","cn":"品牌忠诚（顾客购买同一牌子商品的倾向）"},{"en":"Champagne houses owe their success to brand image.","cn":"香槟公司的成功在于他们的品牌形象。"}]},"british":{"media":{"uk":"media/uk/british__gb_1.mp3","us":"media/us/british__us_1.mp3"},"oxford":{"phon":"ˈbrɪtɪʃ","pos":"adjective","senses":[{"en":"connected with the United Kingdom of Great Britain and Northern Ireland or with the people who live there","cn":"（大不列颠及北爱尔兰）联合王国的；英国的；英国人的","ex":{"en":"the British Government","cn":"英国政府"}},{"en":"the people of Great Britain or the United Kingdom","cn":"联合王国人民；（统称）英国人","g":"[plural]"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"英国的；英国人的；英国文化的","en":"British means belonging or relating to the United Kingdom, or to its people or culture.","ex":{"en":"...the British government.","cn":"英国政府"}},{"pos":"N-PLURAL 复数名词","cn":"英国人","en":"The British are the people of Great Britain."}]},"examples":[{"en":"The survivors of the avalanche included 12 Britons.","cn":"雪崩的幸存者中有 12 名英国人。"},{"en":"He was born in France but his parents are British.","cn":"他生在法国，但父母是英国人。"}]},"breeze":{"media":{"uk":"media/uk/breeze__gb_1.mp3","us":"media/us/breeze__us_1.mp3"},"oxford":{"phon":"briːz","pos":"noun","senses":[{"en":"a light wind","cn":"微风；和风","g":"[countable]","lab":"North American English","ex":{"en":"a sea breeze","cn":"柔和的海风"}},{"en":"a thing that is easy to do","cn":"轻而易举的事","g":"[singular]","lab":"informal","ex":{"en":"It was a breeze.","cn":"这事不费吹灰之力。"}},{"en":"to move in a cheerful and confident way in a particular direction","cn":"轻盈而自信地走","ex":{"en":"She just breezed in and asked me to help.","cn":"她一阵风似的飘然进来，要求我帮她。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"微风；清风","en":"A breeze is a gentle wind.","ex":{"en":"...a cool summer breeze.","cn":"夏日凉爽的微风"}},{"pos":"VERB 动词","cn":"随意轻松地进入；漫步走入","en":"If you breeze into a place or a position, you enter it in a very casual or relaxed manner.","ex":{"en":"Lopez breezed into the quarter-finals of the tournament","cn":"洛佩斯轻松打入了锦标赛的四分之一决赛。"}},{"pos":"VERB 动词","cn":"轻松过关，轻易通过（比赛或测试）","en":"If you breeze through something such as a game or test, you cope with it easily.","ex":{"en":"John seems to breeze effortlessly through his many commitments at work.","cn":"约翰似乎不费吹灰之力就完成了很多工作任务。"}},{"pos":"N-SING 单数名词","cn":"容易办的事","en":"If you say that something is a breeze, you mean that it is very easy to do or to achieve.","ex":{"en":"And after being an office manager for 20 people, handling my own tiny staff of three is a breeze!","cn":"我曾经是管理着20个人的办公室经理，现在领导区区3名员工不费吹灰之力！"}}]},"examples":[{"en":"She just breezed in and asked me to help.","cn":"她一阵风似的飘然进来，要求我帮她。"},{"en":"He breezed through the tests.","cn":"他轻松顺利地通过了这些测试。"}]},"brainchild":{"media":{"uk":"media/uk/brainchild__gb_1.mp3","us":"media/us/brainchild__us_1.mp3"},"oxford":{"phon":"ˈbreɪntʃaɪld","pos":"noun","senses":[{"en":"an idea or invention of one person or a small group of people","cn":"（个人或小群体的）主意，发明","ex":{"en":"The TV programme was the brainchild of the producer.","cn":"该电视节目是制片人的创意。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"思想结晶；创作成果","en":"Someone's brainchild is an idea or invention that they have thought up or created.","ex":{"en":"The record was the brainchild of rock star Bob Geldof.","cn":"这张唱片是摇滚歌星鲍勃·格尔多夫的心血之作。"}}]},"examples":[{"en":"The festival was the brainchild of Reeves.","cn":"这个节庆活动全是里夫斯的主意。"}]},"broadcasting":{"media":{"uk":"media/uk/broadcasting__gb_1.mp3","us":"media/us/broadcasting__us_1.mp3"},"oxford":{"phon":"ˈbrɔːdkɑːstɪŋ","pos":"noun","senses":[{"en":"the business of making and sending out radio and television programmes","cn":"（无线电和电视的）节目制作和播放；广播","ex":{"en":"to work in broadcasting","cn":"从事广播工作"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（电台或电视台节目的）制作播出，播放","en":"Broadcasting is the making and sending out of television and radio programmes.","ex":{"en":"If this happens it will change the face of religious broadcasting.","cn":"如果此事发生，将改变宗教广播的面貌。"}}]},"examples":[{"en":"the British Broadcasting Corporation (= the BBC)","cn":"英国广播公司"},{"en":"to work in broadcasting","cn":"从事广播工作"}],"base":"broadcast"},"bronze":{"media":{"uk":"media/uk/bronze__gb_1.mp3","us":"media/us/bronze__us_1.mp3"},"oxford":{"phon":"brɒnz","pos":"noun","senses":[{"en":"a dark red-brown metal made by mixing copper and tin","cn":"青铜","g":"[uncountable]","ex":{"en":"a bronze statue","cn":"青铜像"}},{"en":"a dark red-brown colour, like bronze","cn":"深红褐色；青铜色","g":"[uncountable]"},{"en":"a work of art made of bronze, for example a statue","cn":"青铜艺术品","g":"[countable]","ex":{"en":"a fine collection of bronzes","cn":"一批珍藏的青铜制品。"}},{"en":"a medal given as third prize in a competition or race","cn":"铜牌；铜质奖章","g":"[countable, uncountable]","ex":{"en":"She got a bronze in the long jump.","cn":"她获得跳远铜牌。"}},{"en":"dark red-brown in colour","cn":"深红棕色的；青铜色的","ex":{"en":"bronze skin","cn":"古铜色的皮肤"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"青铜；铜锡合金","en":"Bronze is a yellowish-brown metal which is a mixture of copper and tin.","ex":{"en":"...a bronze statue of Giorgi Dimitrov.","cn":"乔治·季米特洛夫的青铜塑像"}},{"pos":"N-COUNT 可数名词","cn":"青铜像；青铜雕塑","en":"A bronze is a statue or sculpture made of bronze.","ex":{"en":"...a bronze of Napoleon on horseback.","cn":"一尊拿破仑骑马的青铜像"}},{"pos":"N-COUNT 可数名词","cn":"铜牌","en":"A bronze is a bronze medal ."},{"pos":"COLOUR 颜色词","cn":"青铜色；黄褐色","en":"Something that is bronze is yellowish-brown in colour.","ex":{"en":"Her hair shone bronze and gold.","cn":"她的头发泛着黄褐色的金光。"}}]},"examples":[{"en":"a figure cast in bronze","cn":"一尊青铜铸像"},{"en":"bronze skin","cn":"古铜色的皮肤"}]},"brim":{"oxford":{"phon":"brɪm","pos":"noun","senses":[{"en":"the top edge of a cup, bowl, glass, etc.","cn":"（杯、碗等容器的）边，边沿","lab":"figurative","ex":{"en":"two wine glasses, filled to the brim","cn":"两只斟满的酒杯"}},{"en":"the flat edge around the bottom of a hat that sticks out","cn":"帽檐","ex":{"en":"She watched the crowd from beneath the brim of her hat.","cn":"她从帽檐下注视着人群。"}},{"en":"having the type of brim mentioned","cn":"有…边的","ex":{"en":"a wide-brimmed hat","cn":"宽檐帽"}},{"en":"to be full of something; to fill something","cn":"（使）满，盛满","ex":{"en":"Tears brimmed in her eyes.","cn":"她热泪盈眶。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（帽）檐","en":"The brim of a hat is the wide part that sticks outwards at the bottom.","ex":{"en":"Rain dripped from the brim of his baseball cap.","cn":"雨水从他的棒球帽帽檐上滴落。"}},{"pos":"VERB 动词","cn":"充满；充溢","en":"If someone or something is brimming with a particular quality, they are full of that quality.","ex":{"en":"England are brimming with confidence after two straight wins in the tournament.","cn":"英格兰队在锦标赛中连赢两场后信心大增。"}},{"pos":"VERB 动词","cn":"充满，充盈（泪水）","en":"When your eyes are brimming with tears, they are full of fluid because you are upset, although you are not actually crying.","ex":{"en":"Michael looked at him imploringly, eyes brimming with tears.","cn":"迈克尔满怀乞求地看着他，两眼泪汪汪的。"}},{"pos":"VERB 动词","cn":"装满；充满","en":"If something brims with particular things, it is packed full of them.","ex":{"en":"The flowerbeds brim with a mixture of lilies and roses.","cn":"花坛里长满了百合和玫瑰。"}},{"pos":"PHRASE 短语","cn":"（尤指容器）盛满，装满","en":"If something, especially a container, is filled to the brim or full to the brim with something, it is filled right up to the top.","ex":{"en":"Richard filled her glass right up to the brim","cn":"理查德给她倒了满满一杯。"}},{"pos":"PHRASE 短语","cn":"充满，洋溢（某种感情）","en":"If you are full to the brim with a particular emotion, you feel that emotion so strongly that it is stronger than all other emotions.","ex":{"en":"Her heart beat so fast and she was full to the brim with joy.","cn":"她心跳加快，满心喜悦。"}},{"pos":"","cn":"","en":"相关词组：brim over"}]},"media":{"img":["media/pic/hats_comp.jpg","media/thumb/panama.jpg"],"uk":"media/uk/brim__gb_1.mp3","us":"media/us/brim__us_1.mp3"},"examples":[{"en":"The team were brimming with confidence before the game.","cn":"该队在赛前信心十足。"},{"en":"( figurative ) Her heart was brimming over with happiness.","cn":"她心中洋溢着幸福。"}]},"brushed":{"lemma":"brush","media":{"uk":"media/ldoce/hwd/bre/7/brushed0205.mp3","us":"media/ldoce/hwd/ame/0/laadbrushed.mp3"}},"breed":{"oxford":{"phon":"briːd","pos":"verb","senses":[{"en":"to have sex and produce young","cn":"交配繁殖","g":"[intransitive]","ex":{"en":"Many animals breed only at certain times of the year.","cn":"很多动物只在一年的某些时候交配繁殖。"}},{"en":"to keep animals or plants in order to produce young ones for a particular purpose","cn":"饲养，培育（动植物）","g":"[transitive, intransitive]","lab":"North American English","ex":{"en":"The rabbits are bred for their long coats.","cn":"饲养兔子是为了获取它们的长毛。"}},{"en":"to be the cause of something","cn":"孕育；导致","g":"[transitive]","ex":{"en":"Nothing breeds success like success.","cn":"一事成功，万事亨通。"}},{"en":"to educate somebody in a particular way as they are growing up","cn":"以…方式教育；使养成","g":"[transitive, usually passive]","ex":{"en":"Fear of failure was bred into him at an early age.","cn":"对失败的恐惧在他年幼时便潜移默化地植入他心中。"}},{"en":"a particular type of animal that has been developed by people in a certain way, especially a type of dog, cat or farm animal","cn":"品种（尤指人工培育的狗、猫或牲畜）","ex":{"en":"Labradors and other large breeds of dog","cn":"拉布拉多及其他大型犬"},"pos":"noun"},{"en":"a type of person","cn":"（人的）类型，种类","g":"[usually singular]","ex":{"en":"He represents a new breed of politician.","cn":"他代表着新一类的政治家。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（宠物或牲畜的）种，品种","en":"A breed of a pet animal or farm animal is a particular type of it. For example, terriers are a breed of dog.","ex":{"en":"...rare breeds of cattle","cn":"稀有品种的牛"}},{"pos":"VERB 动词","cn":"饲养；培育","en":"If you breed animals or plants, you keep them for the purpose of producing more animals or plants with particular qualities, in a controlled way.","ex":{"en":"He lived alone, breeding horses and dogs","cn":"他独自一人生活，饲养马匹和狗。"}},{"pos":"VERB 动词","cn":"（动物）繁殖，繁育","en":"When animals breed, they have babies.","ex":{"en":"Frogs will usually breed in any convenient pond","cn":"通常青蛙会在任何条件适宜的池塘中繁殖。"}},{"pos":"VERB 动词","cn":"产生；引起；酿成","en":"If you say that something breeds bad feeling or bad behaviour, you mean that it causes bad feeling or bad behaviour to develop.","ex":{"en":"If they are unemployed it's bound to breed resentment","cn":"如果他们失去工作，一定会产生怨恨。"}},{"pos":"N-COUNT 可数名词","cn":"类型；种类","en":"You can refer to someone or something as one of a particular breed of person or thing when you want to talk about what they are like.","ex":{"en":"Sue is one of the new breed of British women squash players who are making a real impact","cn":"休是英国新一代的女子壁球运动员，她们的影响正在显现出来。"}},{"pos":"PHRASE 短语","cn":"（在某地）出生并长大","en":"Someone who was born and bred in a place was born there and grew up there.","ex":{"en":"I was born and bred in the highlands","cn":"我在高地地区出生和长大。"}},{"pos":"","cn":"","en":"familiarity breeds contempt→see: ;"}]},"media":{"uk":"media/uk/breed__gb_1.mp3","us":"media/us/breed__us_1.mp3"},"examples":[{"en":"Many animals breed only at certain times of the year.","cn":"很多动物只在一年的某个时候交配繁殖。"},{"en":"The rabbits are bred for their long coats.","cn":"饲养兔子是为了获取它们的长毛。"}]},"broadcast":{"oxford":{"phon":"ˈbrɔːdkɑːst","pos":"verb","senses":[{"en":"to send out programmes on television or radio","cn":"播送（电视或无线电节目）；广播","g":"[transitive, intransitive]","lab":"British English","ex":{"en":"The concert will be broadcast live (= at the same time as it takes place) tomorrow evening.","cn":"明晚的音乐会将现场直播。"}},{"en":"to tell a lot of people about something","cn":"散布，传播（信息等）","g":"[transitive]","ex":{"en":"I don't like to broadcast the fact that my father owns the company.","cn":"我不想宣扬这家公司为我父亲所有。"}},{"en":"a radio or television programme","cn":"广播节目；电视节目","lab":"British English","ex":{"en":"a party political broadcast (= for example, before an election)","cn":"政党政治广播节目"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（无线电或电视）广播；广播节目；电视节目","en":"A broadcast is a programme, performance, or speech on the radio or on television.","ex":{"en":"In a broadcast on state radio the government also announced that it was willing to resume peace negotiations.","cn":"在国家电台的广播中，政府也声明愿意重新开始和平谈判。"}},{"pos":"VERB 动词","cn":"（电台或电视台）广播，播出（节目）","en":"To broadcast a programme means to send it out by radio waves, so that it can be heard on the radio or seen on television.","ex":{"en":"The concert will be broadcast live on television and radio","cn":"音乐会将通过电视和广播现场直播。"}}]},"media":{"uk":"media/uk/broadcast__gb_1.mp3","us":"media/us/broadcast__us_1.mp3"},"examples":[{"en":"I don't like to broadcast the fact that my father owns the company.","cn":"我不想宣扬这家公司为我父亲所有。"},{"en":"We watched a live broadcast of the speech (= one shown at the same time as the speech was made).","cn":"我们观看了那场演说的现场直播。"}]},"breathes":{"lemma":"breathe"},"broadly":{"oxford":{"phon":"ˈbrɔːdli","pos":"adverb","senses":[{"en":"generally, without considering details","cn":"大体上；基本上；不考虑细节地","ex":{"en":"Broadly speaking, I agree with you.","cn":"我大体上赞同你的意见。"}},{"en":"if you smile broadly, you smile with your mouth stretched very wide because you are very pleased or are enjoying something very much","cn":"咧开嘴（笑）地；开心（笑）地"}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"一般说来；大致上","en":"You can use broadly to indicate that something is generally true.","ex":{"en":"The President broadly got what he wanted out of his meeting","cn":"总统通过这次会议基本上达到了他的目的。"}}]},"media":{"uk":"media/uk/broadly__gb_1.mp3","us":"media/us/broadly__us_1.mp3"},"examples":[{"en":"Broadly speaking, I agree with you.","cn":"我大体上赞同你的意见。"},{"en":"broadly similar/comparable/equivalent/consistent","cn":"大致相似/相当/相等/一致"}]},"breeding":{"oxford":{"phon":"ˈbriːdɪŋ","pos":"noun","senses":[{"en":"the keeping of animals in order to breed (= produce young) from them","cn":"（为繁殖的）饲养","ex":{"en":"the breeding of horses","cn":"马的繁育"}},{"en":"the producing of young animals, plants, etc.","cn":"（动植物的）生育，繁殖","ex":{"en":"the breeding season","cn":"繁殖季节"}},{"en":"the family or social background that is thought to result in good manners","cn":"教养","ex":{"en":"a sign of good breeding","cn":"良好教养的体现"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"教养","en":"If someone says that a person has breeding, they mean that they think the person is from a good social background and has good manners.","ex":{"en":"It's a sign of good breeding to know the names of all your staff.","cn":"知道所有员工的名字是有良好教养的一种体现。"}}]},"media":{"uk":"media/uk/breeding__gb_1.mp3","us":"media/us/breeding__us_1.mp3"},"examples":[{"en":"a sign of good breeding","cn":"良好教养的体现"},{"en":"the breeding of horses","cn":"马的饲养"}],"base":"breed"},"breakthrough":{"media":{"uk":"media/uk/breakthrough__gb_1.mp3","us":"media/us/breakthrough__us_1.mp3"},"oxford":{"phon":"ˈbreɪkθruː","pos":"noun","senses":[{"en":"an important development that may lead to an agreement or achievement","cn":"重大进展；突破","ex":{"en":"to make/achieve a breakthrough","cn":"取得突破性进展"}},{"en":"in which a performer or type of product is successful for the first time, when it is likely to be even more successful in the future","cn":"突破性的","ex":{"en":"It was a breakthrough album for the band.","cn":"这是该乐队的成名专辑。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"突破；重大进展","en":"A breakthrough is an important development or achievement.","ex":{"en":"The company looks poised to make a significant breakthrough in China","cn":"这家公司看来很有把握在中国取得重大突破。"}}]},"examples":[{"en":"It was a breakthrough album for the band.","cn":"这是该乐队的成名专辑。"},{"en":"a major breakthrough in cancer research","cn":"癌症研究中的重要突破"}]},"brochure":{"media":{"uk":"media/uk/brochure__gb_1.mp3","us":"media/us/brochure__us_1.mp3"},"oxford":{"phon":"ˈbrəʊʃə(r)","pos":"noun","senses":[{"en":"a small magazine or book containing pictures and information about something or advertising something","cn":"资料（或广告）手册","ex":{"en":"a travel brochure","cn":"旅游手册"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（介绍产品或服务信息的）小册子","en":"A brochure is a magazine or thin book with pictures that gives you information about a product or service.","ex":{"en":"...travel brochures.","cn":"旅游小册子"}}]},"examples":[{"en":"a travel brochure","cn":"旅游手册"},{"en":"a holiday brochure","cn":"度假手册"}]},"broker":{"oxford":{"phon":"ˈbrəʊkə(r)","pos":"noun","senses":[{"en":"a person who buys and sells things for other people","cn":"经纪人；掮客","ex":{"en":"Ask advice from an insurance broker.","cn":"咨询一下保险经纪人。"}},{"en":"a person or an organization that buys and sells shares for other people","cn":"证券（或股票）经纪人；证券（或股票）经纪商"},{"en":"a person who arranges the details of an agreement between two groups or countries that disagree or oppose each other","cn":"中间人；掮客","ex":{"en":"He offered to act as a broker between the rebels and the government.","cn":"他提出担任叛军和政府之间的中间人。"}},{"en":"to arrange the details of an agreement, especially between different countries","cn":"安排，协商（协议的细节，尤指在两国间）","ex":{"en":"a peace plan brokered by the UN","cn":"由联合国出面协商的和平计划"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(股票、外汇或商品）经纪人，代理商","en":"A broker is a person whose job is to buy and sell shares, foreign money, or goods for other people."},{"pos":"VERB 动词","cn":"（国家或政府作为中间人）协调，安排","en":"If a country or government brokers an agreement, a ceasefire, or a round of talks, they try to negotiate or arrange it.","ex":{"en":"The United Nations brokered a peace in Mogadishu at the end of March.","cn":"3月末，联合国出面在摩加迪沙进行了和平调解。"}}]},"media":{"uk":"media/uk/broker__gb_1.mp3","us":"media/us/broker__us_1.mp3"},"examples":[{"en":"a peace plan brokered by the UN","cn":"由联合国出面协商的和平计划"},{"en":"an insurance broker","cn":"保险经纪人"}]},"briefly":{"media":{"uk":"media/uk/briefly__gb_1.mp3","us":"media/us/briefly__us_1.mp3"},"oxford":{"phon":"ˈbriːfli","pos":"adverb","senses":[{"en":"for a short time","cn":"短暂地；暂时地","ex":{"en":"He had spoken to Emma only briefly.","cn":"他和埃玛只讲了短短的几句话。"}},{"en":"in few words","cn":"简短地；简要地","ex":{"en":"Briefly, the argument is as follows…","cn":"简言之，理由如下…"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"短暂地","en":"Something that happens or is done briefly happens or is done for a very short period of time.","ex":{"en":"He smiled briefly","cn":"他微微笑了笑。"}},{"pos":"ADV-GRADED 副词","cn":"简要地；简单地","en":"If you say or write something briefly, you use very few words or give very few details.","ex":{"en":"There are four basic alternatives; they are described briefly below.","cn":"有4个基本的选项，简述如下。"}},{"pos":"ADV-GRADED 副词","cn":"简言之；总之","en":"You can say briefly to indicate that you are about to say something in as few words as possible.","ex":{"en":"Briefly, no less than nine of our agents have passed information to us.","cn":"总而言之，至少有9名特工向我们传递了情报。"}}]},"examples":[{"en":"Let me tell you briefly what happened.","cn":"我来大致给你讲一下所发生的事情吧。"},{"en":"He had spoken to Emma only briefly.","cn":"他和埃玛只讲了短短的几句话。"}]},"brave":{"media":{"uk":"media/uk/brave__gb_1.mp3","us":"media/us/brave__us_1.mp3"},"oxford":{"phon":"breɪv","pos":"adjective","senses":[{"en":"willing to do things that are difficult, dangerous or painful; not afraid","cn":"勇敢的；无畏的","ex":{"en":"brave men and women","cn":"英勇无畏的男女"}},{"en":"requiring or showing courage","cn":"需要勇气的；表现勇敢的","ex":{"en":"She took the brave decision to start her own business.","cn":"她做出了勇敢的决定，开始自己创业。"}},{"en":"new in an impressive way","cn":"新颖的；崭新的","lab":"sometimes ironic","ex":{"en":"a vision of a brave new Britain","cn":"令人叹为观止的新英国远景"}},{"en":"to have to deal with somebody/something difficult or unpleasant in order to achieve something","cn":"勇敢面对；冒（风险）；经受（困难）","ex":{"en":"He did not feel up to braving the journalists at the airport.","cn":"他怯于在机场直接面对记者。"},"pos":"verb"},{"en":"people who are brave","cn":"勇敢的人","g":"[plural]","ex":{"en":"America, the land of the free and the home of the brave","cn":"美国，自由者的土地、勇士的家园"},"pos":"noun"},{"en":"a native North American warrior","cn":"美洲印第安武士","g":"[countable]","lab":"old-fashioned","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"勇敢的；无畏的","en":"Someone who is brave is willing to do things which are dangerous, and does not show fear in difficult or dangerous situations.","ex":{"en":"He was not brave enough to report the loss of the documents.","cn":"他没有勇气报告丢失了文件。"}},{"pos":"VERB 动词","cn":"（通常为达到某目标）勇敢面对","en":"If you brave unpleasant or dangerous conditions, you deliberately expose yourself to them, usually in order to achieve something.","ex":{"en":"Thousands have braved icy rain to demonstrate their support.","cn":"数千人在寒冷的天气中冒雨赶来以示他们的支持。"}},{"pos":"N-COUNT 可数名词","cn":"（尤指善于作战的）印第安勇士","en":"A brave is a young Native American man, especially one who is good at fighting."},{"pos":"PHRASE 短语","cn":"装作高兴；强作欢颜","en":"If someone is putting on a brave face or is putting a brave face on a difficult situation, they are pretending that they are happy or satisfied when they are not.","ex":{"en":"He felt disappointed but he tried to put on a brave face","cn":"他感到很失望，但还竭力强装欢笑。"}}]},"examples":[{"en":"She died after a brave fight against cancer.","cn":"她在同癌症进行了顽强的搏斗之后死去了。"},{"en":"I wasn't brave enough to tell her what I thought of her.","cn":"我当时没有勇气告诉她我对她的看法。"}]},"brushwork":{"media":{"uk":"media/uk/brushwork__gb_1.mp3","us":"media/us/brushwork__us_1.mp3"},"oxford":{"phon":"ˈbrʌʃwɜːk","pos":"noun","senses":[{"en":"the particular way in which an artist uses a brush to paint","cn":"（画家的）笔触，画法","lab":"US English","ex":{"en":"the bold brushwork of her abstract paintings","cn":"她抽象绘画的大胆笔触"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（画家的）笔法，画风","en":"An artist's brushwork is their way of using their brush to put paint on a canvas and the effect that this has in the picture.","ex":{"en":"... the texture of the artist's brushwork.","cn":"这位艺术家的笔法特征"}}]}},"brother":{"media":{"uk":"media/uk/brother__gb_1.mp3","us":"media/us/brother__us_1.mp3"},"oxford":{"phon":"ˈbrʌðə(r)","pos":"noun","senses":[{"en":"a boy or man who has the same parents as another person","cn":"哥哥；弟弟","sc":"in family","ex":{"en":"We're brothers.","cn":"我们是亲兄弟。"}},{"en":"used for talking to or talking about other male members of an organization or other men who have the same ideas, purpose, etc. as yourself","cn":"（称男性的共事者或同道）同事，弟兄，伙伴","lab":"old-fashioned","sc":"other men","ex":{"en":"We must work together, brothers!","cn":"我们必须携手工作，伙计们！"}},{"en":"a male member of a religious group, especially a monk","cn":"（同一宗教团体的男性）教友；（尤指）修士","sc":"in religious group","ex":{"en":"Brother Luke","cn":"卢克修士"}},{"en":"used by black people as a form of address for a black man","cn":"（黑人对黑人男子的称呼）","lab":"North American English, informal，，","sc":"form of address"},{"en":"(in the US) a member of a fraternity (= a club for a group of male students at a college or university)","cn":"（美国）大学生联谊会成员","sc":"at college/university"},{"en":"used to express the fact that you are annoyed or surprised","cn":"（表示生气或吃惊）","ex":{"en":"Oh brother!","cn":"天哪！"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（同父母的）兄，弟","en":"Your brother is a boy or a man who has the same parents as you.","ex":{"en":"Oh, so you're Peter's younger brother","cn":"哦，那么你是彼得的弟弟。"}},{"pos":"N-COUNT 可数名词","cn":"兄弟；同胞；教友；国人；同行；同志","en":"You can describe a man as your brother if he belongs to the same race, religion, country, profession, or trade union as you, or if he has similar ideas to you.","ex":{"en":"He told reporters he'd come to be with his Latvian brothers.","cn":"他告诉记者他是来支持拉脱维亚同胞的。"}},{"pos":"N-TITLE; N-COUNT; N-VOC头衔名词；可数名词；称呼名词","cn":"教徒，修士，僧侣（用于头衔）","en":"Brother is a title given to a man who belongs to a religious community such as a monastery.","ex":{"en":"...Brother Otto.","cn":"奥托修士"}},{"pos":"N-IN-NAMES 名称名词","cn":"（用于某些公司或商店的名称中）","en":"Brothers is used in the names of some companies and shops.","ex":{"en":"...the film company Warner Brothers","cn":"华纳兄弟电影公司"}}]},"examples":[{"en":"Edward was the youngest of the Kennedy brothers.","cn":"爱德华是肯尼迪弟兄中最小的一个。"},{"en":"We must work together, brothers!","cn":"我们必须携手工作，伙计们！"}]},"break":{"media":{"uk":"media/uk/break__gb_1.mp3","us":"media/us/break__us_1.mp3"},"oxford":{"phon":"breɪk","pos":"verb","senses":[{"en":"to be damaged and separated into two or more parts, as a result of force; to damage something in this way","cn":"（使）破，裂，碎","g":"[intransitive, transitive]","lab":"especially British English","sc":"in pieces","ex":{"en":"All the windows broke with the force of the blast.","cn":"爆炸的巨大力量震碎了所有的窗户。"}},{"en":"to stop working as a result of being damaged; to damage something and stop it from working","cn":"弄坏；损坏；坏掉","g":"[intransitive, transitive]","sc":"stop working","ex":{"en":"My watch has broken.","cn":"我的表坏了。"}},{"en":"to cut the surface of the skin and make it bleed","cn":"弄破；使流血","g":"[transitive]","sc":"skin","ex":{"en":"The dog bit me but didn't break the skin.","cn":"那条狗咬了我，但没咬破皮肤。"}},{"en":"to do something that is against the law; to not keep a promise, etc.","cn":"违犯；背弃","g":"[transitive]","sc":"law/promise","ex":{"en":"I had broken the law and deserved to be punished.","cn":"我触犯了法律，应该受到惩罚。"}},{"en":"to stop doing something for a while, especially when it is time to eat or have a drink","cn":"稍停；暂停","g":"[intransitive, transitive]","lab":"especially British English","sc":"stop for short time","ex":{"en":"Let's break for lunch.","cn":"我们休息一会儿，吃午饭。"}},{"en":"to interrupt something so that it ends suddenly","cn":"打断；中断","g":"[transitive]","sc":"end something","ex":{"en":"She broke the silence by coughing.","cn":"她的咳嗽声打破了寂静。"}},{"en":"to make something end by using force or strong action","cn":"强行终止；破坏","g":"[transitive]","sc":"end something","ex":{"en":"an attempt to break the year-long siege","cn":"试图冲破长达一年的围困"}},{"en":"to end a connection with something or a relationship with somebody","cn":"终止，断绝（关系、联系）","g":"[transitive]","sc":"end something","ex":{"en":"He broke all ties with his parents.","cn":"他断绝了与父母的一切关系。"}},{"en":"to manage to get away from or out of a position in which they have been caught","cn":"设法逃脱；努力挣脱","g":"[intransitive]","sc":"escape","ex":{"en":"He finally managed to break free from his attacker.","cn":"他终于设法逃脱了袭击他的人。"}},{"en":"to destroy something or make somebody/something weaker; to become weak or be destroyed","cn":"（被）摧毁，削弱","g":"[transitive, intransitive]","sc":"destroy, be destroyed","ex":{"en":"to break somebody’s morale/resistance/resolve/spirit","cn":"瓦解某人的士气／抵抗／决心／精神"}},{"en":"to win a game in which it is your opponent's turn to serve (= hit the ball across the net first)","cn":"破发（在对方发球局获胜）","g":"[transitive]","sc":"in tennis","ex":{"en":"Williams broke her opponent's serve five times.","cn":"威廉姆斯五次破掉对手的发球局。"}},{"en":"to make somebody feel so sad, lonely, etc. that they cannot live a normal life","cn":"使心碎；使十分悲伤；使孤寂","g":"[transitive]","sc":"make somebody feel bad","ex":{"en":"The death of his wife broke him completely.","cn":"妻子的死使他悲痛欲绝。"}},{"en":"to change suddenly, usually after a period when it has been fine","cn":"（常指好天气）突变","g":"[intransitive]","sc":"of weather","ex":{"en":"On the third day the weather broke and they had a violent storm.","cn":"第三天，天气变坏，下了一场猛烈的暴风雨。"}},{"en":"to show an opening","cn":"露出缝隙；散开","g":"[intransitive]","sc":"of clouds","ex":{"en":"The clouds broke and the sun came out.","cn":"云开日出。"}},{"en":"to come up through the surface of water in the sea, a pool, etc.","cn":"浮出水面","sc":"surface","ex":{"en":"When his head broke the surface he took in deep gulps of air.","cn":"当他的头浮出水面时，他大口吸了几口气。"}},{"en":"when the day or dawn or a storm breaks, it begins","cn":"开始；（风暴）发作","g":"[intransitive]","sc":"of day/dawn/storm","ex":{"en":"Dawn was breaking when they finally left.","cn":"他们终于离开时正是破晓时分。"}},{"en":"if a piece of news breaks, it becomes known","cn":"透露；传开","g":"[intransitive]","sc":"of news","ex":{"en":"There was a public outcry when the scandal broke.","cn":"丑闻一传开，舆论一片哗然。"}},{"en":"to be the first to tell somebody some bad news","cn":"（第一个将坏消息向某人）公布，透露，说出","g":"[transitive]","sc":"of news","ex":{"en":"Who's going to break it to her?","cn":"由谁来把这事告诉她呢？"}},{"en":"if somebody’s voice breaks, it changes its tone because of emotion","cn":"（因激动）变调","g":"[intransitive]","sc":"of voice","ex":{"en":"Her voice broke as she told us the dreadful news.","cn":"她告诉我们这可怕的消息时，声音都变了。"}},{"en":"when a boy’s voice breaks, it becomes permanently deeper at about the age of 13 or 14","cn":"（指男孩在 13 或 14 岁时嗓音）变粗，变低","g":"[intransitive]","sc":"of voice"},{"en":"to do something better, faster, etc. than anyone has ever done it before","cn":"打破（纪录）","g":"[transitive]","sc":"a record","ex":{"en":"She had broken the world 100 metres record.","cn":"她打破了 100 米世界纪录。"}},{"en":"when waves break, they fall and are dissolved into foam, usually near land","cn":"拍岸；迸溅","g":"[intransitive]","sc":"of waves","ex":{"en":"the sound of waves breaking on the beach","cn":"浪涛拍岸的声音"}},{"en":"to find the meaning of something secret","cn":"破译；破解","g":"[transitive]","sc":"something secret","ex":{"en":"to break a code","cn":"破译密码"}},{"en":"to change a banknote for coins","cn":"把…换成零钱；破开","g":"[transitive]","lab":"especially North American English","sc":"money","ex":{"en":"Can you break a twenty-dollar bill?","cn":"可以给我破开二十美元的钞票吗？"}},{"en":"a short period of time when you stop what you are doing and rest, eat, etc.","cn":"间歇；休息","g":"[countable]","lab":"especially North American English","sc":"short stop","ex":{"en":"She was on her lunch break.","cn":"她正在午休。"},"pos":"noun"},{"en":"a period of time between lessons at school","cn":"课间休息","g":"[uncountable]","lab":"both British English","sc":"short stop","ex":{"en":"Come and see me at break.","cn":"课间休息时来见我。"},"pos":"noun"},{"en":"a period of time when something stops before starting again","cn":"间断；暂停","g":"[countable]","lab":"especially British English","sc":"short stop","ex":{"en":"Employees can take a career break of up to one year.","cn":"雇员可以有长达一年的停职期。"},"pos":"noun"},{"en":"a short period of time when a television or radio show stops for advertisements","cn":"（穿插在电视或广播节目中的）广告时间","g":"[countable]","sc":"short stop","ex":{"en":"More news after the break.","cn":"广告后继续报道新闻。"},"pos":"noun"},{"en":"a short holiday","cn":"短期休假","g":"[countable]","sc":"holiday/vacation","ex":{"en":"We had a weekend break in New York.","cn":"我们在纽约度过了一个周末假日。"},"pos":"noun"},{"en":"the moment when a situation or a relationship that has existed for a time changes, ends or is interrupted","cn":"（持续一段时间的状况或关系的）改变，终止，中断","g":"[singular]","sc":"change in situation","ex":{"en":"I wanted to leave but was nervous about making the break.","cn":"我想离开，但又担心改变现状。"},"pos":"noun"},{"en":"a space or an opening between two or more things","cn":"间隔；缝隙","g":"[countable]","sc":"opening/space","ex":{"en":"We could see the moon through a break in the clouds.","cn":"我们能从云缝里看到月亮。"},"pos":"noun"},{"en":"an opportunity to do something, usually to get something that you want or to achieve success","cn":"机会；机遇","g":"[countable]","lab":"informal","sc":"opportunity","ex":{"en":"I got my lucky break when I won a ‘Young Journalist of the Year’ competition.","cn":"我时来运转，在“年度最佳青年记者”竞赛中取胜。"},"pos":"noun"},{"en":"a place where something, especially a bone in your body, has broken","cn":"破裂；骨折","g":"[countable]","sc":"of bone","ex":{"en":"The X-ray showed there was no break in his leg.","cn":"X 光照片显示他的腿没有骨折。"},"pos":"noun"},{"en":"a win in a game in which your opponent is serving","cn":"破发","g":"[countable]","sc":"in tennis","ex":{"en":"It was her second break in the set.","cn":"这是本盘比赛中她第二次破掉对手的发球局。"},"pos":"noun"},{"en":"a series of successful shots by one player; the number of points scored in a series of successful shots","cn":"单杆；单杆得分","g":"[countable]","sc":"in billiards/snooker","ex":{"en":"He's put together a magnificent break.","cn":"他这杆球打得很不错。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"打破；摔碎","en":"When an object breaks or when you break it, it suddenly separates into two or more pieces, often because it has been hit or dropped.","ex":{"en":"He fell through the window, breaking the glass","cn":"他撞破玻璃从窗口摔了下去。"}},{"pos":"V-ERG 及物/不及物动词","cn":"折断（骨头）；骨折","en":"If you break a part of your body such as your leg, your arm, or your nose, or if a bone breaks, you are injured because a bone cracks or splits.","ex":{"en":"She broke a leg in a skiing accident","cn":"她在一次滑雪事故中摔断了一条腿。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（表层、盖子或密封）破裂；撕开","en":"If a surface, cover, or seal breaks or if something breaks it, a hole or tear is made in it, so that a substance can pass through.","ex":{"en":"Once you've broken the seal of a bottle there's no way you can put it back together again","cn":"一旦你撕开瓶子的密封条，你就无法再把它复原。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）（工具或机器）损坏","en":"When a tool or piece of machinery breaks or when you break it, it is damaged and no longer works.","ex":{"en":"When the clutch broke, the car was locked into second gear","cn":"离合器失灵后，汽车只能在二挡行驶。"}},{"pos":"VERB 动词","cn":"破坏，违反（规则、承诺或协议）","en":"If you break a rule, promise, or agreement, you do something that you should not do according to that rule, promise, or agreement.","ex":{"en":"We didn't know we were breaking the law.","cn":"我们不知道自己在犯法。"}},{"pos":"VERB 动词","cn":"挣脱；解脱","en":"If you break free or loose, you free yourself from something or escape from it.","ex":{"en":"She broke free by thrusting her elbow into his chest.","cn":"她用肘猛击他的胸部，挣脱了出来。"}},{"pos":"VERB 动词","cn":"结束（困难或不利局面）；打破（僵局）","en":"If someone breaks something, especially a difficult or unpleasant situation that has existed for some time, they end it or change it.","ex":{"en":"The Home Secretary aims to break the vicious circle between disadvantage and crime","cn":"内政大臣力图打破贫困和犯罪之间的恶性循环。"}},{"pos":"VERB 动词","cn":"打破（沉默）","en":"If someone or something breaks a silence, they say something or make a noise after a long period of silence.","ex":{"en":"Hugh broke the silence. 'Is she always late?' he asked","cn":"休打破了沉默，问道：“她总是迟到吗？”"}},{"pos":"N-COUNT 可数名词","cn":"（天气的）放晴","en":"If there is a break in the cloud or weather, it changes and there is a short period of sunshine or fine weather.","ex":{"en":"A sudden break in the cloud allowed rescuers to spot Michael Benson.","cn":"天气的突然放晴帮助救援人员找到了迈克尔·本森。"}},{"pos":"VERB 动词","cn":"（与…）决裂；断绝（联系）；放弃","en":"If you break with a group of people or a traditional way of doing things, or you break your connection with them, you stop being involved with that group or stop doing things in that way.","ex":{"en":"In 1959, Akihito broke with imperial tradition by marrying a commoner","cn":"明仁天皇在1959年打破皇室传统，娶了一位平民女子为妻。"}},{"pos":"VERB 动词","cn":"（使）摆脱，（使）戒除（习惯）","en":"If you break a habit or if someone breaks you of it, you no longer have that habit.","ex":{"en":"If you continue to smoke, keep trying to break the habit","cn":"如果你还在吸烟的话，就尽量戒除这个习惯吧。"}},{"pos":"VERB 动词","cn":"瓦解…的决心；使丧失勇气；毁掉…的前程","en":"To break someone means to destroy their determination and courage, their success, or their career.","ex":{"en":"He never let his jailers break him","cn":"他决不会让监狱看守们摧毁他的意志。"}},{"pos":"VERB 动词","cn":"短暂休息；稍停","en":"If someone breaks for a short period of time, they rest or change from what they are doing for a short period.","ex":{"en":"They broke for lunch.","cn":"他们停下来吃午饭。"}},{"pos":"N-COUNT 可数名词","cn":"间歇；小憩","en":"A break is a short period of time when you have a rest or a change from what you are doing, especially if you are working or if you are in a boring or unpleasant situation.","ex":{"en":"They may be able to help with childcare so that you can have a break","cn":"他们可以帮忙照料孩子，这样你就可以歇一歇了。"}},{"pos":"N-COUNT 可数名词","cn":"短假","en":"A break is a short holiday.","ex":{"en":"They are currently taking a short break in Spain.","cn":"他们目前正在西班牙休短假。"}},{"pos":"VERB 动词","cn":"（为短暂歇息而）打断（旅程）","en":"If you break your journey somewhere, you stop there for a short time so that you can have a rest.","ex":{"en":"Because of the heat we broke our journey at a small country hotel.","cn":"由于天气炎热，我们在一家乡村小旅馆停下来稍作歇息。"}},{"pos":"VERB 动词","cn":"减弱（势头）；减轻（力度）","en":"To break the force of something such as a blow or fall means to weaken its effect, for example by getting in the way of it.","ex":{"en":"He sustained serious neck injuries after he broke someone's fall.","cn":"有人坠落压在他身上，致使他颈部受重伤。"}},{"pos":"VERB 动词","cn":"（消息在报纸、电视或电台）发布，传播","en":"When a piece of news breaks, people hear about it from the newspapers, television, or radio.","ex":{"en":"The news broke that the Prime Minister had resigned","cn":"据报道首相已经辞职。"}},{"pos":"VERB 动词","cn":"（通常以委婉的方式）透露，告知（坏消息）","en":"When you break a piece of bad news to someone, you tell it to them, usually in a kind way.","ex":{"en":"Then Louise broke the news that she was leaving me","cn":"然后路易丝挑明了她要离开我。"}},{"pos":"N-COUNT 可数名词","cn":"机遇；机会；好运","en":"A break is a lucky opportunity that someone gets to achieve something.","ex":{"en":"He went into TV and got his first break playing opposite Sid James in the series 'Citizen James'.","cn":"他进入了电视圈，获得的第一个机会是在连续剧《公民詹姆斯》中与锡德·詹姆斯演对手戏。"}},{"pos":"VERB 动词","cn":"打破（纪录）","en":"If you break a record, you beat the previous record for a particular achievement.","ex":{"en":"Carl Lewis has broken the world record in the 100 metres","cn":"卡尔·刘易斯已经打破了百米赛跑的世界纪录。"}},{"pos":"VERB 动词","cn":"（天）破晓","en":"When day or dawn breaks, it starts to grow light after the night has ended.","ex":{"en":"They continued the search as dawn broke.","cn":"天放亮后他们继续搜寻。"}},{"pos":"VERB 动词","cn":"（波浪)减势，落下","en":"When a wave breaks, it passes its highest point and turns downwards, for example when it reaches the shore.","ex":{"en":"Danny listened to the waves breaking against the shore.","cn":"丹尼聆听着波浪拍岸的声音。"}},{"pos":"VERB 动词","cn":"破解，破译（密码）","en":"If you break a secret code, you work out how to understand it.","ex":{"en":"It was feared they could break the Allies' codes.","cn":"恐怕他们会破译盟军的密码。"}},{"pos":"VERB 动词","cn":"（因悲伤或害怕嗓音）突变，变调","en":"If someone's voice breaks when they are speaking, it changes its sound, for example because they are sad or afraid.","ex":{"en":"Godfrey's voice broke, and halted.","cn":"戈弗雷声音都变了，停顿下来。"}},{"pos":"VERB 动词","cn":"（男孩嗓音）变粗","en":"When a boy's voice breaks, it becomes deeper and sounds more like a man's voice.","ex":{"en":"He sings with the strained discomfort of someone whose voice hasn't quite broken.","cn":"他唱得很拘谨，声音听起来像是某个还没完全变声的男孩。"}},{"pos":"VERB 动词","cn":"（天气）突变；（风暴）骤起","en":"If the weather breaks or a storm breaks, it suddenly becomes rainy or stormy after a period of sunshine.","ex":{"en":"I've been waiting for the weather to break","cn":"我一直在等待着暴风雨的到来。"}},{"pos":"VERB 动词","cn":"（网球比赛中）破，赢得（对手的发球局）","en":"In tennis, if you break your opponent's serve, you win a game in which your opponent is serving.","ex":{"en":"He broke McEnroe's serve.","cn":"他破了麦肯罗的发球局。"}},{"pos":"PHRASE 短语","cn":"破晓时分","en":"The break of day or the break of dawn is the time when it begins to grow light after the night.","ex":{"en":"'I,' he finished poetically, 'will watch over you to the break of day.'","cn":"“我，”他以富有诗意的语言结尾，“将守候着你，直至晨光初露。”"}},{"pos":"CONVENTION 惯用语","cn":"别烦我了","en":"You can say 'give me a break' to show that you are annoyed by what someone has said or done.","ex":{"en":"'I'm a real intellectual-type guy, Tracy,' James joked. 'Oh, give me a break,' Tracy moaned.","cn":"“我可是个货真价实的高智商小伙儿，特雷西。”詹姆斯开玩笑地说道。“哦，别烦我了，”特雷西抱怨道。"}},{"pos":"PHRASE 短语","cn":"逃离；离开","en":"If you make a break or make a break for it, you run to escape from something.","ex":{"en":"The moment had come to make a break or die","cn":"那个时候不跑就没命了。"}},{"pos":"","cn":"","en":"to break the bank→see: ; to break cover→see: ; to break even→see: ; to break new ground→see: ; to break someone's heart→see: ; all hell breaks loose→see: ; to break the ice→see: ; to break ranks→see: ; to break wind→see: ;"},{"pos":"","cn":"","en":"相关词组：break away break down break in break into break off break out break through break up"}]},"examples":[{"en":"Expenditure on the project breaks down as follows: wages $10m, plant $4m, raw materials $5m.","cn":"这项工程的支出费用分项列明如下：工资 1 000 万元，设备 400 万元，原料 500 万元。"},{"en":"She needed to break out of her daily routine and do something exciting.","cn":"她需要从日常事务中解脱出来，找点有意思的事做。"}]},"brick":{"media":{"uk":"media/uk/brick__gb_1.mp3","us":"media/us/brick__us_1.mp3"},"oxford":{"phon":"brɪk","pos":"noun","senses":[{"en":"baked clay used for building walls, houses and other buildings; an individual block of this","cn":"砖；砖块","g":"[countable, uncountable]","ex":{"en":"The school is built of brick.","cn":"那所学校是用砖建造的。"}},{"en":"a plastic or wooden block, used as a toy for young children to build things with","cn":"积木","g":"[countable]"},{"en":"a friend that you can rely on when you need help","cn":"可靠的朋友","g":"[countable, usually singular]","lab":"British English, old-fashioned, informal，，，，","ex":{"en":"Thanks for looking after the children today—you're a real brick.","cn":"谢谢你今天照看孩子——你真是个好人。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"砖；砖料","en":"Bricks are rectangular blocks of baked clay used for building walls, which are usually red or brown. Brick is the material made up of these blocks.","ex":{"en":"She built bookshelves out of bricks and planks.","cn":"她用砖和木板制作书架。"}},{"pos":"N-SING 单数名词","cn":"患难之交；可靠的朋友","en":"If you say that someone is a brick, you mean that they have helped you or supported you when you were in a difficult situation.","ex":{"en":"You were a brick, a real friend in need.","cn":"你很够朋友，是真正的患难之交。"}},{"pos":"PHRASE 短语","cn":"白费力气；枉费心机","en":"If you are banging your head against a brick wall, what you are saying or doing is not having any effect although you keep saying or doing it.","ex":{"en":"I wanted to sort out this problem with him, but it was like banging my head against a brick wall.","cn":"我曾想跟他把这个问题给解决了，但结果徒劳无功。"}},{"pos":"PHRASE 短语","cn":"碰壁；陷入困境","en":"If you hit a brick wall or come up against a brick wall, you are unable to continue or make progress because something stops you.","ex":{"en":"After that my career just seemed to hit a brick wall","cn":"在那之后我的事业似乎就陷入了困境。"}},{"pos":"PHRASE 短语","cn":"（尤指视为投资的）房产","en":"You can use bricks and mortar to refer to houses and other buildings, especially when they are considered as an investment.","ex":{"en":"Paying rent simply helps to line the pockets of landlords. It's far better to put your money into bricks and mortar of your own","cn":"租房子只会鼓了房东的腰包，自己投资买房要合算得多。"}},{"pos":"","cn":"","en":"to come down on somebody like a ton of bricks→see: ;"},{"pos":"","cn":"","en":"相关词组：brick up"}]},"examples":[{"en":"They put their money into bricks and mortar.","cn":"他们把钱投资到了房产上。"},{"en":"The school is built of brick.","cn":"那所学校是用砖建造的。"}]},"bracket":{"media":{"uk":"media/uk/bracket__gb_1.mp3","us":"media/us/bracket__us_1.mp3"},"oxford":{"phon":"ˈbrækɪt","pos":"noun","senses":[{"en":"either of a pair of marks, ( ), placed around extra information in a piece of writing or part of a problem in mathematics","cn":"括号","g":"[usually plural]","lab":"both British English","ex":{"en":"Publication dates are given in brackets after each title.","cn":"出版日期括于书名后面。"}},{"en":"either of a pair of marks, [ ], placed at the beginning and end of extra information in a text, especially comments made by an editor","cn":"方括号","g":"[usually plural]","lab":"North American English"},{"en":"prices, etc. within a particular range","cn":"（价格、年龄、收入等的）组级，等级","ex":{"en":"People in the lower income brackets will not be able to afford this.","cn":"低收入阶层的人们将无法承担这一费用。"}},{"en":"a piece of wood, metal or plastic fixed to the wall to support a shelf, lamp, etc.","cn":"（固定在墙上的）托架，支架","ex":{"en":"fixed to the wall on a bracket","cn":"通过支架固定在墙上"}},{"en":"to put words, information, etc. between brackets","cn":"用括弧括上","pos":"verb"},{"en":"to consider people or things to be similar or connected in some way","cn":"把…等同考虑；把…相提并论","g":"[often passive]","ex":{"en":"It is unfair to bracket together those who cannot work with those who will not.","cn":"把不能工作的人和不愿工作的人等同起来是不公平的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（收入、年龄、价格等的）范围，等级段","en":"If you say that someone or something is in a particular bracket, you mean that they come within a particular range, for example a range of incomes, ages, or prices.","ex":{"en":"...a 33% top tax rate on everyone in these high-income brackets","cn":"对所有这些高收入人群征收的33%的最高税率"}},{"pos":"N-COUNT 可数名词","cn":"（固定在墙上的）托架，支架，角撑架","en":"Brackets are pieces of metal, wood, or plastic that are fastened to a wall in order to support something such as a shelf.","ex":{"en":"Fix the beam with the brackets and screws.","cn":"把横梁用托架和螺丝固定。"}},{"pos":"VERB 动词","cn":"把…归为一类；把…相提并论","en":"If two or more people or things are bracketed together, they are considered to be similar or related in some way.","ex":{"en":"The Magi, Bramins, and Druids were bracketed together as men of wisdom","cn":"东方三博士、婆罗门和德鲁伊特都被视为富有智慧的人。"}},{"pos":"N-COUNT 可数名词","cn":"括号，括弧（美国英语中称作parentheses）","en":"Brackets are a pair of written marks that you place round a word, expression, or sentence in order to indicate that you are giving extra information. In British English, curved marks like these are also called brackets, but in American English, they are called parentheses .","ex":{"en":"The prices in brackets are special rates for the under 18s","cn":"括号中的价格是年龄在18岁以下的消费者可以享受的特别优惠价。"}},{"pos":"N-COUNT 可数名词","cn":"（数学上的）括号","en":"Brackets are pair of marks that are placed around a series of symbols in a mathematical expression to indicate that those symbols function as one item within the expression."}]},"examples":[{"en":"It is unfair to bracket together those who cannot work with those who will not.","cn":"把不能工作的人和不愿工作的人等同看待是不公平的。"},{"en":"Most of the houses are out of our price bracket.","cn":"大多数房子都超出我们的价格范围。"}]},"breaths":{"lemma":"breath","media":{"uk":"media/uk/breath__gb_1.mp3","us":"media/us/breath__us_1.mp3"}},"britain":{"media":{"uk":"media/uk/britain__gb_1.mp3","us":"media/us/britain__us_1.mp3"},"oxford":{"phon":"ˈbrɪtn","pos":"noun","senses":[{"en":"the island containing England, Scotland and Wales","cn":"不列颠（包括英格兰、苏格兰及威尔士）"}]}},"broadway":{"media":{"uk":"media/uk/broadway__gb_1.mp3","us":"media/us/broadway__us_1.mp3"},"oxford":{"phon":"ˈbrɔːdweɪ","pos":"noun","senses":[{"en":"a street in New York City where there are many theatres, sometimes used to refer to the US theatre industry in general","cn":"百老汇（美国纽约市戏院集中的一条大街）；（美国的）戏剧业","ex":{"en":"a Broadway musical","cn":"百老汇音乐剧"}}]},"examples":[{"en":"The play opened on Broadway in 2008.","cn":"该剧于 2008 年在百老汇首演。"},{"en":"a Broadway musical","cn":"百老汇音乐剧"}]},"bright":{"media":{"uk":"media/uk/bright__gb_1.mp3","us":"media/us/bright__us_1.mp3"},"oxford":{"phon":"braɪt","pos":"adjective","senses":[{"en":"full of light; shining strongly","cn":"光线充足的；明亮的","ex":{"en":"bright light/sunshine","cn":"明亮的光线；明媚的阳光"}},{"en":"strong and easy to see","cn":"鲜艳夺目的","ex":{"en":"I like bright colours.","cn":"我喜欢艳丽的色彩。"}},{"en":"giving reason to believe that good things will happen; likely to be successful","cn":"有希望的；大有可能成功的","ex":{"en":"This young musician has a bright future.","cn":"这位年轻的音乐家前途无量。"}},{"en":"intelligent; quick to learn","cn":"聪明的；悟性强的","lab":"especially North American English","ex":{"en":"the brightest pupil in the class","cn":"班里最聪明的学生"}},{"en":"cheerful and lively","cn":"快活而生气勃勃的","ex":{"en":"His eyes were bright and excited.","cn":"他目光发亮，兴奋不已。"}},{"en":"brightly","cn":"光亮地；明亮地","ex":{"en":"The stars were shining bright.","cn":"星光闪烁。"},"pos":"adverb"},{"en":"the headlights on a vehicle set to a position in which they are shining as brightly as possible and not directed downwards","cn":"（车辆的）前大灯，头灯","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（颜色）鲜艳的，明亮的","en":"A bright colour is strong and noticeable, and not dark.","ex":{"en":"...a bright red dress.","cn":"鲜红的连衣裙"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（光线）充足的，明亮的","en":"A bright light, object, or place is shining strongly or is full of light.","ex":{"en":"...a bright October day","cn":"10月的一天，天气晴朗"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"聪明的；伶俐的","en":"If you describe someone as bright, you mean that they are quick at learning things.","ex":{"en":"I was convinced that he was brighter than average.","cn":"我确信他比一般人聪明。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（主意）聪明的，巧妙的","en":"A bright idea is clever and original.","ex":{"en":"There are lots of books crammed with bright ideas","cn":"许多书里都有很多绝妙的想法。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"快乐的；活泼的；开朗的","en":"If someone looks or sounds bright, they look or sound cheerful and lively.","ex":{"en":"The boy was so bright and animated","cn":"这个男孩活泼开朗，充满活力。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（未来）光明的，有希望的","en":"If the future is bright, it is likely to be pleasant or successful.","ex":{"en":"Both had successful careers and the future looked bright","cn":"两个人都事业有成，前程似锦。"}},{"pos":"N-COUNT 可数名词","cn":"（汽车或其他车辆）打开的前灯","en":"The brights on a car or other vehicle are the headlights when they are switched on fully."},{"pos":"PHRASE 短语","cn":"看光明的一面；抱乐观态度","en":"If you look on the bright side, you try to be cheerful about a bad situation by thinking of some advantages that could result from it, or thinking that it is not as bad as it could have been."}]},"examples":[{"en":"Although he grew up in the country, he's always had a taste for the bright lights.","cn":"尽管他是在农村长大的，他始终对城市的五光十色情有独钟。"},{"en":"The win last week was the only bright spot in their last ten games.","cn":"上周的胜利是他们最近十场比赛中唯一振奋人心的一次。"}]},"broadcaster":{"oxford":{"phon":"ˈbrɔːdkɑːstə(r)","pos":"noun","senses":[{"en":"a person whose job is presenting or talking on television or radio programmes","cn":"广播员；（电视或电台的）节目主持人","ex":{"en":"She is a writer and broadcaster on environmental matters.","cn":"她是环境问题方面的作家兼节目主持人。"}},{"en":"a company that sends out television or radio programmes","cn":"电视台；广播公司","ex":{"en":"the new Australian rugby broadcaster, Channel Ten","cn":"新的澳大利亚橄榄球广播公司第十频道"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（电台或电视台的）广播员，播音员，节目主持人","en":"A broadcaster is someone who gives talks or takes part in interviews and discussions on radio or television programmes.","ex":{"en":"...the prominent naturalist and broadcaster, Sir David Attenborough.","cn":"著名的博物学家兼主持人戴维·阿滕伯勒爵士"}}]},"media":{"uk":"media/uk/broadcaster__gb_1.mp3","us":"media/us/broadcaster__us_1.mp3"},"examples":[{"en":"a well-known broadcaster","cn":"一位著名的播音员"},{"en":"the British broadcaster Channel 4","cn":"英国第四频道电视台"}]},"bring":{"media":{"uk":"media/uk/bring__gb_1.mp3","us":"media/us/bring__us_1.mp3"},"oxford":{"phon":"brɪŋ","pos":"verb","senses":[{"en":"to come to a place with somebody/something","cn":"带…到某处；带来；取来","sc":"come with somebody/something","ex":{"en":"Don't forget to bring your books with you.","cn":"别忘了把书带来。"}},{"en":"to give or provide somebody/something with something","cn":"提供；供给","sc":"give/provide","ex":{"en":"They brought us some good news.","cn":"他们给我们带来了好消息。"}},{"en":"to cause something","cn":"导致；引起","sc":"cause","ex":{"en":"The revolution brought many changes.","cn":"这场革命导致很多变化。"}},{"en":"to cause somebody/something to be in a particular condition or place","cn":"使处于某种状况；使到某地","sc":"cause","ex":{"en":"to bring a meeting to an end","cn":"结束会议"}},{"en":"used to move a speech or piece of writing on from one point to the next","cn":"（在演讲或写作中）使转到","sc":"cause","ex":{"en":"This brings me to the second point I'd like to make:…","cn":"由此，我将说到第二点：…"}},{"en":"to make somebody/something move in a particular direction or way","cn":"使朝（某方向或按某方式）移动","sc":"make somebody/something move","ex":{"en":"The judge brought his hammer down on the table.","cn":"法官在桌子上敲下他的木槌。"}},{"en":"to start legal action against somebody/something; to make somebody/something answer a case in court","cn":"对某人提起（诉讼）；控告","sc":"legal action","ex":{"en":"to bring charges/legal action/proceedings against somebody","cn":"控告某人；对某人提起诉讼；控告某人"}},{"en":"to force yourself to do something","cn":"强迫自己做某事","sc":"force yourself","ex":{"en":"She could not bring herself to tell him the news.","cn":"她难以开口把这个消息告诉他。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（随身）带来","en":"If you bring someone or something with you when you come to a place, they come with you or you have them with you.","ex":{"en":"Remember to bring an apron or an old shirt to protect your clothes","cn":"记得带一个围裙或者一件旧衬衫来，免得弄脏你的衣服。"}},{"pos":"VERB 动词","cn":"把…带到；移动","en":"If you bring something somewhere, you move it there.","ex":{"en":"Reaching into her pocket, she brought out a cigarette","cn":"她伸手从兜里掏出来一支烟。"}},{"pos":"VERB 动词","cn":"带来；拿来","en":"If you bring something that someone wants or needs, you get it for them or carry it to them.","ex":{"en":"He went and poured a brandy for Dena and brought it to her","cn":"他走过去为德娜倒了一杯白兰地，端到她跟前。"}},{"pos":"VERB 动词","cn":"把…引到；把…带到","en":"To bring something or someone to a place or position means to cause them to come to the place or move into that position.","ex":{"en":"I told you about what brought me here","cn":"我告诉过你是什么把我带到这儿的。"}},{"pos":"VERB 动词","cn":"带给；介绍；引进","en":"If you bring something new to a place or group of people, you introduce it to that place or cause those people to hear or know about it.","ex":{"en":"...a brave reporter who had risked death to bring the story to the world.","cn":"一位冒着生命危险向世人报道此事的勇敢记者"}},{"pos":"VERB 动词","cn":"使处于（…状态或环境）","en":"To bring someone or something into a particular state or condition means to cause them to be in that state or condition.","ex":{"en":"He brought the car to a stop in front of the square","cn":"他在广场前把车停了下来。"}},{"pos":"VERB 动词","cn":"导致；带来；产生","en":"If something brings a particular feeling, situation, or quality, it makes people experience it or have it.","ex":{"en":"He called on the United States to play a more effective role in bringing peace to the region","cn":"他呼吁美国在实现该地区的和平方面发挥更加富有成效的作用。"}},{"pos":"VERB 动词","cn":"（某段时间）发生","en":"If a period of time brings a particular thing, it happens during that time.","ex":{"en":"For Sandro, the new year brought disaster","cn":"对桑德罗来说，新的一年带来的是灾难。"}},{"pos":"VERB 动词","cn":"（对某人）提起（诉讼）；将（某人）送上（法庭）","en":"If you bring a legal action against someone or bring them to trial, you officially accuse them of doing something illegal.","ex":{"en":"He campaigned relentlessly to bring charges of corruption against former members of the government","cn":"为了将前政府成员以贪污腐败的罪名送上法庭，他持续不懈地奔走游说。"}},{"pos":"VERB 动词","cn":"提供，制作，播出（电视或广播节目）","en":"If a television or radio programme is brought to you by an organization, they make it, broadcast it, or pay for it to be made or broadcast.","ex":{"en":"You're listening to Science in Action, brought to you by the BBC World Service","cn":"您正在收听的是《科学在行动》，由BBC全球广播频道制作播出。"}},{"pos":"VERB 动词","cn":"把（某人）带到（或引到）（某话题）","en":"When you are talking, you can say that something brings you to a particular point in order to indicate that you have now reached that point and are going to talk about a new subject.","ex":{"en":"Which brings me to a delicate matter I should like to raise","cn":"这就把我带到了一个我想提及的敏感问题上。"}},{"pos":"VERB 动词","cn":"强迫（自己）做（令人伤心、窘迫或讨厌的事）","en":"If you cannot bring yourself to do something, you cannot do it because you find it too upsetting, embarrassing, or disgusting.","ex":{"en":"It is all very tragic and I am afraid I just cannot bring myself to talk about it at the moment.","cn":"这是件很不幸的事，恐怕现在我还无法开口谈论此事。"}},{"pos":"","cn":"","en":"to bring something alive→see: ; to bring something to bear→see: ; to bring the house down→see: ; to bring up the rear→see: ;"},{"pos":"PHRASAL VERB 短语动词","cn":"谈及；提出","en":"If you bring up a particular subject, you introduce it into a discussion or conversation.","ex":{"en":"He brought up a subject rarely raised during the course of this campaign","cn":"他提出了一个在这次运动中很少被提及的话题。"}},{"pos":"PHRASAL VERB 短语动词","cn":"呕吐；咳出","en":"If someone brings up food or wind, food or air is forced up from their stomach through their mouth.","ex":{"en":"It's hard for the baby to bring up wind.","cn":"婴儿不容易打出嗝来。"}},{"pos":"","cn":"","en":"相关词组：bring about bring along bring around bring back bring down bring forward bring in bring off bring on bring out bring round bring to bring up"}]},"examples":[{"en":"Local residents were angry at not being brought in on (= asked for their opinion about) the new housing proposal.","cn":"新的住房方案未征求当地居民的意见，对此他们感到愤怒。"},{"en":"The meeting has been brought forward from 10 May to 3 May.","cn":"会议已由 5 月 10 号提前到 5 月 3 号。"}]},"brief":{"media":{"uk":"media/uk/brief__gb_1.mp3","us":"media/us/brief__us_1.mp3"},"oxford":{"phon":"briːf","pos":"adjective","senses":[{"en":"lasting only a short time; short","cn":"短时间的；短暂的","ex":{"en":"a brief visit/meeting/conversation","cn":"短时间的访问／会议／交谈"}},{"en":"using few words","cn":"简洁的；简单的","ex":{"en":"a brief description/summary/overview","cn":"简明扼要的描述／总结／概述"}},{"en":"short and not covering much of the body","cn":"过短的；暴露身体的","ex":{"en":"a brief skirt","cn":"超短裙"}},{"en":"the instructions that a person is given explaining what their job is and what their duties are","cn":"任务简介；指示","lab":"British English","ex":{"en":"It wasn't part of his brief to speak to the press.","cn":"交付他的任务不包括向新闻界发言。"},"pos":"noun"},{"en":"a legal case that is given to a lawyer to argue in court; a piece of work for a barrister","cn":"（向出庭律师提供的）诉讼摘要；委托辩护","lab":"British English, law，，","ex":{"en":"Will you accept this brief?","cn":"你接受这个案件吗？"},"pos":"noun"},{"en":"a written summary of the facts that support one side of a legal case that will be presented to a court","cn":"辩护状","lab":"North American English, law，，","pos":"noun"},{"en":"a solicitor or a defence lawyer","cn":"事务律师；辩护律师","lab":"British English, informal，，","ex":{"en":"I want to see my brief.","cn":"我想见我的律师。"},"pos":"noun"},{"en":"the detailed instructions or information that are given at such a meeting","cn":"详细指示；详情介绍","g":"[countable, uncountable]","lab":"especially North American English","ex":{"en":"Officials are pushing for this target to be included in the next presidential brief.","cn":"官员正敦促在下一次总统的简报中一定要包括这个目标。"},"pos":"noun"},{"en":"to give somebody information about something so that they are prepared to deal with it","cn":"给（某人）指示；向（某人）介绍情况","ex":{"en":"I expect to be kept fully briefed at all times.","cn":"我希望随时向我报告所有情况。"},"pos":"verb"},{"en":"to give a lawyer, especially a barrister, the main facts of a legal case so that it can be argued in court","cn":"向（出庭律师）提供诉讼摘要","lab":"British English, law，，","pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简短的；短暂的","en":"Something that is brief lasts for only a short time.","ex":{"en":"She once made a brief appearance on television","cn":"她曾经在电视上短暂露面。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（讲话或文章）简短的，简洁的","en":"A brief speech or piece of writing does not contain too many words or details.","ex":{"en":"In a brief statement, he concentrated entirely on international affairs","cn":"他作了一个简短的声明，集中阐述了在国际事务方面的立场。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"简明扼要的","en":"If you are brief, you say what you want to say in as few words as possible.","ex":{"en":"Now please be brief — my time is valuable","cn":"请长话短说——我的时间宝贵。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（时间）短的，短暂的","en":"You can describe a period of time as brief if you want to emphasize that it is very short.","ex":{"en":"For a few brief minutes we forgot the anxiety and anguish.","cn":"短短几分钟我们就忘记了焦虑与苦恼。"}},{"pos":"N-PLURAL 复数名词","cn":"短内裤","en":"Men's or women's underpants can be referred to as briefs .","ex":{"en":"A bra and a pair of briefs lay on the floor.","cn":"地板上有一个胸罩和一条短内裤。"}},{"pos":"VERB 动词","cn":"（尤指就某项工作或某一重大事件）向…简要介绍情况","en":"If someone briefs you, especially about a piece of work or a serious matter, they give you information that you need before you do it or consider it.","ex":{"en":"A Defense Department spokesman briefed reporters","cn":"一位国防部发言人向记者们简要介绍了情况。"}},{"pos":"N-COUNT 可数名词","cn":"正式委托；指示","en":"If someone gives you a brief, they officially give you responsibility for dealing with a particular thing.","ex":{"en":"...customs officials with a brief to stop foreign porn coming into Britain.","cn":"受命阻止国外淫秽出版物流入英国的海关官员"}},{"pos":"PHRASE 短语","cn":"简短地","en":"If you refer to something in brief, you are referring to a shortened version of it with few details.","ex":{"en":"...and now sport in brief.","cn":"现在播报体育简讯"}},{"pos":"PHRASE 短语","cn":"简言之；总之","en":"You can say in brief to indicate that you are about to say something in as few words as possible or to give a summary of what you have just said.","ex":{"en":"In brief, take no risks.","cn":"总之，不能冒险。"}},{"pos":"","cn":"","en":"相关词组：brief against"}]},"examples":[{"en":"Officials are pushing for this target to be included in the next presidential brief.","cn":"官员正敦促在下一次总统的简报中一定要包括这个目标。"},{"en":"The officer briefed her on what to expect.","cn":"军官简要向她说了一下可能遇到的情况。"}]},"branched":{"lemma":"branch"},"breeds":{"lemma":"breed"},"breath":{"media":{"uk":"media/uk/breath__gb_1.mp3","us":"media/us/breath__us_1.mp3"},"oxford":{"phon":"breθ","pos":"noun","senses":[{"en":"the air that you take into your lungs and send out again","cn":"呼吸的空气","g":"[uncountable]","ex":{"en":"His breath smelt of garlic.","cn":"他呼出的气中有大蒜味。"}},{"en":"an amount of air that enters the lungs at one time","cn":"一次吸入的空气","g":"[countable]","ex":{"en":"Take a deep breath and try to relax.","cn":"深呼吸，尽量放松。"}},{"en":"a small amount of something; slight evidence of something","cn":"微量；迹象","g":"[singular]","lab":"formal","ex":{"en":"a breath of suspicion/scandal","cn":"一丝怀疑；丑闻的嫌疑"}},{"en":"a slight movement of air","cn":"（空气的）微微流动，拂动","g":"[singular]","lab":"literary","ex":{"en":"It was a still day, without a breath of wind.","cn":"那天很平静，没有一丝风。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"呼出的气体；气息","en":"Your breath is the air that you let out through your mouth when you breathe. If someone has bad breath, their breath smells unpleasant.","ex":{"en":"I could smell the whisky on his breath","cn":"我能闻到他呼出的威士忌的味道。"}},{"pos":"N-VAR 可变名词","cn":"吸气","en":"When you take a breath, you breathe in once.","ex":{"en":"He took a deep breath, and began to climb the stairs","cn":"他深吸了一口气，然后开始爬楼梯。"}},{"pos":"N-SING 单数名词","cn":"（风或气流的）一丝，丝毫","en":"If you say that there is not a breath of wind or air, you are emphasizing that there is no wind and the air is very still.","ex":{"en":"Not even a breath of wind stirred the pine branches.","cn":"一丝风也没有，松树枝条纹丝不动。"}},{"pos":"N-SING 单数名词","cn":"微量；少许","en":"A breath of something, is a small amount of it.","ex":{"en":"It was left to Martina to add a breath of common sense to the proceedings.","cn":"这件事交由马丁娜处理，她会使整个过程显得更符合情理一些。"}},{"pos":"PHRASE 短语","cn":"（到室外）呼吸新鲜空气，透口气","en":"If you go outside for a breath of fresh air or for a breath of air, you go outside because it is unpleasantly warm indoors."},{"pos":"PHRASE 短语","cn":"令人耳目一新的事物；新鲜刺激的东西","en":"If you describe something new or different as a breath of fresh air, you mean that it makes a situation or subject more interesting or exciting.","ex":{"en":"Her brisk treatment of an almost taboo subject was a breath of fresh air.","cn":"她把这个近乎禁忌的话题处理得很轻松，令人耳目一新。"}},{"pos":"PHRASE 短语","cn":"喘过气来；恢复正常呼吸","en":"When you get your breath back after doing something energetic, you start breathing normally again.","ex":{"en":"I reached out a hand to steady myself against the house while I got my breath back.","cn":"我伸出一只手抵住墙壁撑着身子，让自己喘口气。"}},{"pos":"PHRASE 短语","cn":"喘口气；歇口气","en":"When you catch your breath while you are doing something energetic, you stop for a short time so that you can start breathing normally again.","ex":{"en":"He had stopped to catch his breath and make sure of his directions.","cn":"他曾停下来歇口气，同时确定一下方向。"}},{"pos":"PHRASE 短语","cn":"（通常因为震惊）倒吸一口冷气","en":"If something makes you catch your breath, it makes you take a short breath of air, usually because it shocks you.","ex":{"en":"Kenny caught his breath as Nikko nearly dropped the bottle.","cn":"尼科差点儿把瓶子摔了，这让肯尼倒吸了一口气。"}},{"pos":"PHRASE 短语","cn":"喘口气；歇口气","en":"If you do not have time to draw breath, you do not have time to have a break from what you are doing."},{"pos":"PHRASE 短语","cn":"屏息；止住呼吸","en":"If you hold your breath, you make yourself stop breathing for a few moments, for example because you are under water.","ex":{"en":"I held my breath and sank under the water.","cn":"我屏住呼吸沉入水底。"}},{"pos":"PHRASE 短语","cn":"屏息静气（焦急或激动地等待）","en":"If you say that someone is holding their breath, you mean that they are waiting anxiously or excitedly for something to happen.","ex":{"en":"The whole world holds its breath for this speech.","cn":"整个世界都屏住呼吸等待这一讲话。"}},{"pos":"PHRASE 短语","cn":"不指望（某事发生）","en":"If you say that you won't hold your breath, you mean that you do not expect something to happen even though someone has suggested that it might.","ex":{"en":"'Next thing you know, I'll be dancing at your wedding,' he cried. 'Don't hold your breath,' my father replied.","cn":"“你瞧，下一件事是，我会在你的婚礼上跳舞，”他大声说。“你休想，”我父亲答道。"}},{"pos":"PHRASE 短语","cn":"最后一口气","en":"When someone takes their last breath, they die.","ex":{"en":"His wife sat with him until he drew his last breath.","cn":"他的妻子坐在他跟前，直到他咽下最后一口气。"}},{"pos":"PHRASE 短语","cn":"喘不过气；上气不接下气","en":"If you are out of breath, you are breathing very quickly and with difficulty because you have been doing something energetic.","ex":{"en":"There she was, slightly out of breath from running.","cn":"她在那儿，跑得有点儿喘不过气来。"}},{"pos":"PHRASE 短语","cn":"但同时/但紧接着（尤用于谴责某人的言论自相矛盾）","en":"You can use in the same breath or in the next breath to indicate that someone says two very different or contradictory things, especially when you are criticizing them.","ex":{"en":"He hailed this week's arms agreement but in the same breath expressed suspicion about the motivations of the United States.","cn":"他为本周达成的武器协议而欢呼，但同时又对美国的动机表示怀疑。"}},{"pos":"PHRASE 短语","cn":"呼吸短促；呼吸困难","en":"If you are short of breath, you find it difficult to breathe properly, for example because you are ill. You can also say that someone suffers from shortness of breath .","ex":{"en":"She felt short of breath and flushed","cn":"她感到呼吸困难，脸颊绯红。"}},{"pos":"PHRASE 短语","cn":"（美或惊讶得）令（人）喘不过气来；使（人）惊叹","en":"If you say that something takes your breath away, you are emphasizing that it is extremely beautiful or surprising.","ex":{"en":"I heard this song on the radio and it just took my breath away.","cn":"我是从收音机里听到这首歌的，它令我惊叹不已。"}},{"pos":"PHRASE 短语","cn":"压低嗓音；低声地","en":"If you say something under your breath, you say it in a very quiet voice, often because you do not want other people to hear what you are saying.","ex":{"en":"Walsh muttered something under his breath.","cn":"沃尔什小声嘟囔了一句。"}},{"pos":"PHRASE 短语","cn":"白费唇舌","en":"If someone says you are wasting your breath, they mean that the person you are talking to will not take any notice and so there is no point saying anything to them.","ex":{"en":"The tone of her voice told him he was wasting his breath.","cn":"她的语气使他明白他是在白费口舌。"}},{"pos":"","cn":"","en":"with bated breath→see: ; to fight for breath→see: ;"}]},"examples":[{"en":"He praised my work and in the same breath told me I would have to leave.","cn":"他称赞了一番我的工作，但紧接着却对我说不得不辞退我。"},{"en":"She said she'd do it this week, but don't hold your breath!","cn":"她说她这个星期要干，不过你可别因此眼巴巴干等！"}]},"branches":{"lemma":"branch"},"breast":{"media":{"uk":"media/uk/breast__gb_1.mp3","us":"media/us/breast__us_1.mp3"},"oxford":{"phon":"brest","pos":"noun","senses":[{"en":"either of the two round soft parts at the front of a woman’s body that produce milk when she has had a baby","cn":"（女子的）乳房","g":"[countable]","sc":"part of body","ex":{"en":"She put the baby to her breast.","cn":"她开始给婴儿哺乳。"}},{"en":"the similar, smaller part on a man’s body, which does not produce milk","cn":"（男子的）退化乳房","g":"[countable]","sc":"part of body"},{"en":"the top part of the front of your body, below your neck","cn":"胸部；胸脯","g":"[countable]","lab":"literary","sc":"part of body","ex":{"en":"He cradled the child against his breast.","cn":"他把孩子抱在怀里。"}},{"en":"the part of a piece of clothing that covers your chest","cn":"前胸部分","g":"[countable]","sc":"clothing","ex":{"en":"A row of medals was pinned to the breast of his coat.","cn":"他的外套胸前别着一排勋章。"}},{"en":"the front part of a bird’s body","cn":"（鸟的）胸部","g":"[countable]","sc":"of bird","ex":{"en":"breast feathers","cn":"胸部羽毛"}},{"en":"meat from the front part of the body of a bird or an animal","cn":"（鸟或动物的）胸脯肉","g":"[countable, uncountable]","sc":"meat","ex":{"en":"chicken/turkey breasts","cn":"鸡／火鸡胸脯肉"}},{"en":"having the type of chest or breasts mentioned","cn":"胸脯（或乳房）…的","sc":"-breasted","ex":{"en":"a small-breasted/full-breasted woman","cn":"乳房小／丰满的女子"}},{"en":"the part of the body where the feelings and emotions are thought to be","cn":"心窝；内心","g":"[countable]","lab":"literary","sc":"heart","ex":{"en":"a troubled breast","cn":"忧虑的心情"}},{"en":"to reach the top of a hill, etc.","cn":"登上…的顶部","ex":{"en":"As they breasted the ridge, they saw the valley and lake before them.","cn":"他们到达山脊时山谷和湖泊尽收眼底。"},"pos":"verb"},{"en":"to push through something, touching it with your chest","cn":"挺胸从…中挤过","ex":{"en":"He strode into the ocean, breasting the waves.","cn":"他挺胸顶着波浪大步走进海里。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（妇女的）乳房","en":"A woman's breasts are the two soft, round parts on her chest that can produce milk to feed a baby.","ex":{"en":"She wears a low-cut dress which reveals her breasts","cn":"她穿了一件露乳沟的低胸连衣裙。"}},{"pos":"N-COUNT 可数名词","cn":"胸；胸部；胸膛","en":"A person's breast is the upper part of his or her chest.","ex":{"en":"He struck his breast in a dramatic gesture.","cn":"他动作夸张地捶打着自己的胸膛。"}},{"pos":"N-COUNT 可数名词","cn":"胸怀；内心","en":"The breast is often considered to be the part of your body where your emotions are.","ex":{"en":"The verse rose up to fire his breast with inspiration","cn":"这首诗激发了他的灵感。"}},{"pos":"N-COUNT 可数名词","cn":"（鸟类的）胸脯","en":"A bird's breast is the front part of its body.","ex":{"en":"The cock's breast is tinged with chestnut.","cn":"这只公鸡胸部羽毛呈浅栗色，带有白色细条纹。"}},{"pos":"N-SING 单数名词","cn":"（衬衫、夹克或外套的）胸部","en":"The breast of a shirt, jacket, or coat is the part which covers the top part of the chest.","ex":{"en":"He moved out from beneath an awning, reaching for something inside the breast of his overcoat","cn":"他离开遮阳篷，手伸进大衣前胸部找东西。"}},{"pos":"N-VAR 可变名词","cn":"（禽鸟或羊的）胸脯肉","en":"You can refer to piece of meat that is cut from the front of a bird or lamb as breast.","ex":{"en":"...a chicken breast with vegetables.","cn":"鸡脯肉拌蔬菜"}},{"pos":"PHRASE 短语","cn":"捶胸（表示气愤或悲伤）","en":"If you say that someone beats their breast, you are emphasizing that they are very angry or upset about something, or that they are pretending to be very angry or upset about it.","ex":{"en":"The president beat his breast and called that deal a mistake.","cn":"总裁捶胸顿足，称那是个错误的交易。"}},{"pos":"PHRASE 短语","cn":"坦白；如实承认","en":"If you make a clean breast of something, you tell someone the truth about yourself or about something wrong that you have done.","ex":{"en":"I might as well make a clean breast of it. I have been living as a woman since 1975.","cn":"我还是坦白的好。我从1975起就变成女人了。"}}]},"examples":[{"en":"As they breasted the ridge, they saw the valley and lake before them.","cn":"他们到达山脊时山谷和湖泊尽收眼底。"},{"en":"He strode into the ocean, breasting the waves.","cn":"他挺胸顶着波浪大步走进海里。"}]},"brake":{"media":{"uk":"media/uk/brake__gb_1.mp3","us":"media/us/brake__us_1.mp3"},"oxford":{"phon":"breɪk","pos":"noun","senses":[{"en":"a device for slowing or stopping a vehicle","cn":"刹车；制动器；车闸","lab":"British English","ex":{"en":"to put/slam on the brakes","cn":"踩／猛踩刹车"}},{"en":"a thing that stops something or makes it difficult","cn":"阻力；障碍","ex":{"en":"High interest rates are a brake on the economy.","cn":"高利率阻碍了经济发展。"}},{"en":"to go slower or make a vehicle go slower using the brake","cn":"用闸减速；刹（车）","ex":{"en":"The car braked and swerved.","cn":"那辆车减慢车速并来了个急转弯。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"制动器；刹车；车闸","en":"Brakes are devices in a vehicle that make it go slower or stop.","ex":{"en":"The brakes began locking","cn":"制动器开始锁定。"}},{"pos":"VERB 动词","cn":"刹车；用刹车使（车）减速；刹住（车）","en":"When a vehicle or its driver brakes, or when a driver brakes a vehicle, the driver makes it slow down or stop by using the brakes.","ex":{"en":"He heard tires squeal as the car braked to avoid a collision","cn":"为避免相撞而刹车时，他听到了轮胎与地面刺耳的摩擦声。"}},{"pos":"N-COUNT 可数名词","cn":"抑制因素；约束","en":"You can use brake in a number of expressions to indicate that something has slowed down or stopped.","ex":{"en":"Illness had put a brake on his progress","cn":"疾病使他的进展放缓。"}}]},"examples":[{"en":"She had to brake hard to avoid running into the car in front.","cn":"她不得不猛踩刹车，以免撞上前面的车。"},{"en":"The car braked and swerved.","cn":"那辆车减慢车速并来了个急转弯。"}]},"bred":{"lemma":"breed","media":{"uk":"media/uk/bred__gb_1.mp3","us":"media/us/bred__us_1.mp3"}},"branded":{"oxford":{"phon":"ˈbrændɪd","pos":"adjective","senses":[{"en":"made by a well-known company and having that company’s name on it","cn":"名牌的","ex":{"en":"branded drugs/goods/products","cn":"名牌药／商品／产品"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（产品）名牌的，有品牌的","en":"A branded product is one which is made by a well-known manufacturer and has the manufacturer's label on it.","ex":{"en":"Supermarket lines are often cheaper than branded goods.","cn":"超市的商品常常比品牌货便宜。"}}]},"media":{"uk":"media/uk/branded__gb_1.mp3","us":"media/us/branded__us_1.mp3"},"examples":[{"en":"branded drugs/goods/products","cn":"名牌药/商品/产品"}],"base":"brand"},"bra":{"oxford":{"phon":"brɑː","pos":"noun","senses":[{"en":"a piece of women’s underwear worn to cover and support the breasts","cn":"胸罩；文胸","lab":"formal"},{"en":"a tightly fitting cover that is put over the front end of a car to protect it","cn":"（汽车前部的）活动罩，车头罩","lab":"North American English"}]},"collins":{"senses":[{"pos":"","cn":"胸罩；乳罩","en":"A bra is a piece of underwear that women wear to support their breasts."}]},"media":{"uk":"media/uk/bra__gb_1.mp3","us":"media/us/bra__us_1.mp3"}},"brass":{"media":{"img":["media/pic/brass_musicalinstruments_comp.jpg","media/thumb/trumpet.jpg"],"uk":"media/uk/brass__gb_1.mp3","us":"media/us/brass__us_1.mp3"},"oxford":{"phon":"brɑːs","pos":"noun","senses":[{"en":"a bright yellow metal made by mixing copper and zinc; objects made of brass","cn":"黄铜；黄铜制品","g":"[uncountable]","sc":"metal","ex":{"en":"solid brass fittings/door handles","cn":"纯黄铜配件／门把手"}},{"en":"the musical instruments made of metal, such as trumpets or French horns, that form a band or section of an orchestra; the people who play them","cn":"（管弦乐团的）铜管乐器，铜管乐器组","g":"[uncountable + singular or plural verb]","sc":"musical instruments","ex":{"en":"music for piano, strings and brass","cn":"钢琴、弦乐器和铜管乐器的合奏乐曲"}},{"en":"a decorated piece of brass used as an attractive object, especially a round flat piece attached to a horse’s harness","cn":"黄铜饰品（尤指马挽具上的黄铜圆片）","g":"[countable]","lab":"British English","sc":"for a horse"},{"en":"a flat piece of brass with words or a picture on it, fixed to the floor or wall of a church in memory of somebody who has died","cn":"黄铜纪念牌（钉在教堂的地上或墙上以纪念死者，上面刻有文字或雕像）","g":"[countable]","lab":"especially British English","sc":"in church","ex":{"en":"a memorial brass","cn":"黄铜纪念牌"}},{"en":"the people who are in the most important positions in a company, an organization, etc.","cn":"（公司、机构等的）最高负责人，要员，头目","g":"[uncountable + singular or plural verb]","lab":"especially North American English","sc":"important people"},{"en":"money","cn":"钱","g":"[uncountable]","lab":"British English, old-fashioned, informal，，，，","sc":"money"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（尤用于制作装饰品和乐器的）黄铜","en":"Brass is a yellow-coloured metal made from copper and zinc. It is used especially for making ornaments and musical instruments.","ex":{"en":"The instrument is beautifully made in brass.","cn":"这个仪器是用黄铜制成的，非常漂亮。"}},{"pos":"N-SING 单数名词","cn":"（交响乐队的）铜管乐乐器组，铜管乐器","en":"The brass is the section of an orchestra which consists of brass wind instruments such as trumpets and horns.","ex":{"en":"He once again raised his baton and brought in the brass.","cn":"他再次举起指挥棒，让铜管乐部加入进来。"}},{"pos":"N-COUNT 可数名词","cn":"（常见于教堂的）黄铜纪念牌","en":"Brasses are flat pieces of brass with writing or a picture cut into them, which are often found in churches."},{"pos":"N-SING-COLL 单数集合名词","cn":"（军队或其他机构的）高级军官，高层人物","en":"In the army or in other organizations, the brass are the people in the highest positions.","ex":{"en":"The brass are reluctant to fraternise with the enlisted men.","cn":"高级军官不愿意与大兵们称兄道弟。"}},{"pos":"PHRASE 短语","cn":"讨论基本事实；探讨实质问题","en":"If you get down to brass tacks, you discuss the basic, most important facts of a situation.","ex":{"en":"Angola's ruling party was due to get down to brass tacks today with a debate on the party's record.","cn":"安哥拉执政党预定在今天就有关该党执政记录的问题进行实质性讨论。"}}]},"examples":[{"en":"music for piano, strings and brass","cn":"钢琴、弦乐器和铜管乐器的合奏乐曲"},{"en":"The girls' outdoor track team has grabbed the brass ring seven times.","cn":"女子室外径赛运动队已经七次夺冠。"}]},"brow":{"media":{"uk":"media/uk/brow__gb_1.mp3","us":"media/us/brow__us_1.mp3"},"oxford":{"phon":"braʊ","pos":"noun","senses":[{"en":"the part of the face above the eyes and below the hair","cn":"额头","lab":"literary","ex":{"en":"The nurse mopped his fevered brow.","cn":"护士擦拭了他发烫的前额。"}},{"en":"the line of hair above the eye","cn":"眉；眉毛","g":"[usually plural]","ex":{"en":"One dark brow rose in surprise.","cn":"一道乌黑的眉毛惊奇地挑起。"}},{"en":"the top part of a hill","cn":"山脊；坡顶","g":"[usually singular]","ex":{"en":"The path disappeared over the brow of the hill.","cn":"小径过山顶后消失了。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"额；额头","en":"Your brow is your forehead.","ex":{"en":"He wiped his brow with the back of his hand","cn":"他用手背擦了擦前额。"}},{"pos":"","cn":"","en":"to knit your brow→see: ;"},{"pos":"N-COUNT 可数名词","cn":"眉；眉毛","en":"Your brows are your eyebrows.","ex":{"en":"He had thick brown hair and shaggy brows.","cn":"他一头浓密的棕色头发，眉毛乱糟糟的。"}},{"pos":"N-COUNT 可数名词","cn":"山脊；坡顶","en":"The brow of a hill is the top part of it.","ex":{"en":"He was on the look-out just below the brow of the hill.","cn":"他就在山脊下负责警戒。"}}]},"examples":[{"en":"One dark brow rose in surprise.","cn":"一道乌黑的眉毛因惊奇而挑起。"},{"en":"The nurse mopped his fevered brow.","cn":"护士擦拭了他发烫的前额。"}]},"bricks":{"lemma":"brick","media":{"uk":"media/uk/brick__gb_1.mp3","us":"media/us/brick__us_1.mp3"}},"breathlessly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unable to breathe easily, especially because you are unhealthy","cn":""},{"en":"having difficulty breathing, especially because you have just been running, climbing stairs etc","cn":""}]},"examples":[{"en":"The long climb left Jan feeling breathless.","cn":"","src":"ld"},{"en":"They waited, breathless with anticipation.","cn":"","src":"ld"}],"media":{"uk":"media/uk/breathlessly__gb_1.mp3","us":"media/us/breathlessly__us_1.mp3"},"oxford":{"phon":"ˈbreθləsli","pos":"adverb","senses":[{"en":"with difficulty in breathing","cn":"（使）气喘吁吁的，上气不接下气的","ex":{"en":"panting breathlessly","cn":"气喘吁吁"}},{"en":"in a strongly emotional way; in a way that makes people feel strong emotions","cn":"呼吸困难：以强烈的情感方式；以一种让人感到强烈的情感的方式","lab":"formal","ex":{"en":"The trial was breathlessly reported by the national media.","cn":"全国媒体屏息地报道了这次审判。"}}]}},"breakdown":{"media":{"uk":"media/uk/breakdown__gb_1.mp3","us":"media/us/breakdown__us_1.mp3"},"oxford":{"phon":"ˈbreɪkdaʊn","pos":"noun","senses":[{"en":"an occasion when a vehicle or machine stops working","cn":"（车辆或机器的）故障，损坏","g":"[countable]","ex":{"en":"a breakdown on the motorway","cn":"在高速公路上出的故障"}},{"en":"a failure of a relationship, discussion or system","cn":"（关系）破裂；（讨论、系统）失败","g":"[countable, uncountable]","ex":{"en":"The only ground for divorce is the irretrievable breakdown of the marriage.","cn":"离婚的唯一理由是婚姻破裂，不可挽回。"}},{"en":"detailed information that you get by studying a set of figures","cn":"数字细目；分类","g":"[countable, usually singular]","ex":{"en":"First, let's look at a breakdown of the costs.","cn":"我们首先看一下成本的详细数字。"}},{"en":"the process of a substance breaking into the parts of which it is made","cn":"分解","g":"[uncountable]","lab":"specialist","ex":{"en":"the breakdown of proteins in the digestive system","cn":"蛋白质在消化系统中的分解"}},{"en":"a period of serious mental illness in which somebody is unable to deal with normal life","cn":"精神崩溃","g":"[countable]","lab":"old-fashioned","ex":{"en":"It all became too much and he had some sort of breakdown.","cn":"这一切变得太过分了，他有些崩溃了。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（关系的）破裂；（计划、讨论等的）失败，结束","en":"The breakdown of something such as a relationship, plan, or discussion is its failure or ending.","ex":{"en":"...the breakdown of talks between the US and EU officials.","cn":"美国和欧盟官员间谈判的破裂"}},{"pos":"N-COUNT 可数名词","cn":"神经衰弱；精神崩溃","en":"If you have a breakdown, you become very depressed, so that you are unable to cope with your life.","ex":{"en":"My personal life was terrible. My mother had died, and a couple of years later I had a breakdown","cn":"我个人的生活一团糟。母亲去世了，几年后我又患上了神经衰弱。"}},{"pos":"N-COUNT 可数名词","cn":"（汽车或机器的）故障，损坏","en":"If a car or a piece of machinery has a breakdown, it stops working.","ex":{"en":"Her old car was unreliable, so the trip was plagued by breakdowns","cn":"她的旧车老不听使唤，一路上总是出故障。"}},{"pos":"N-COUNT 可数名词","cn":"分类；细目列表","en":"A breakdown of something is a list of its separate parts.","ex":{"en":"The organisers were given a breakdown of the costs.","cn":"向组织者提供了一份开支细目。"}}]},"examples":[{"en":"First, let's look at a breakdown of the costs.","cn":"我们首先看一下成本的详细数字。"},{"en":"The breakdown of the negotiations was not unexpected.","cn":"谈判的失败是预料之中的事。"}]},"brush":{"oxford":{"phon":"brʌʃ","pos":"verb","senses":[{"en":"to clean, polish or make something smooth with a brush","cn":"（用刷子）刷净，刷亮，刷平顺","g":"[transitive]","ex":{"en":"to brush your hair/teeth","cn":"梳头；刷牙"}},{"en":"to remove or try to remove something from a place or surface with a brush or with your hand","cn":"（用刷子或手）拂，掸，擦掉","g":"[transitive, intransitive]","ex":{"en":"He brushed the dirt off his jacket.","cn":"他拂掉夹克衫上的灰尘。"}},{"en":"to put something, for example oil, milk or egg, on something using a brush","cn":"（用刷子）抹，涂","g":"[transitive]","ex":{"en":"Brush the pastry with beaten egg.","cn":"用刷子把打匀的鸡蛋抹在油酥面团上。"}},{"en":"to touch somebody/something lightly while moving close to them/it","cn":"轻擦，掠过（某人／某物）","g":"[intransitive, transitive]","ex":{"en":"She brushed past him.","cn":"她和他擦肩而过。"}},{"en":"an object made of short stiff hairs (called bristles) or wires set in a block of wood or plastic, usually attached to a handle. Brushes are used for many different jobs, such as cleaning, painting and tidying your hair.","cn":"刷子；毛刷；画笔","g":"[countable]","ex":{"en":"a paintbrush","cn":"画笔"},"pos":"noun"},{"en":"an act of brushing","cn":"刷","g":"[singular]","ex":{"en":"to give your teeth a good brush","cn":"好好刷一刷牙"},"pos":"noun"},{"en":"a light touch made in passing something/somebody","cn":"轻擦；掠过","g":"[singular]","ex":{"en":"the brush of his lips on her cheek","cn":"他的嘴唇在她脸上的轻轻一碰"},"pos":"noun"},{"en":"a short unfriendly meeting with somebody; an occasion when you nearly experience something unpleasant","cn":"小冲突；稍有不快的场合","g":"[countable]","ex":{"en":"She had a nasty brush with her boss this morning.","cn":"她今天早晨和老板闹得挺别扭的。"},"pos":"noun"},{"en":"land covered by small trees or bushes","cn":"灌木丛","g":"[uncountable]","ex":{"en":"a brush fire","cn":"灌木丛火"},"pos":"noun"},{"en":"the tail of a fox","cn":"狐狸尾巴","g":"[countable]","pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"刷子；毛刷","en":"A brush is an object which has a large number of bristles or hairs fixed to it. You use brushes for painting, for cleaning things, and for tidying your hair.","ex":{"en":"We gave him paint and brushes","cn":"我们给了他油漆和几把刷子。"}},{"pos":"VERB 动词","cn":"（用刷子）刷","en":"If you brush something or brush something such as dirt off it, you clean it or tidy it using a brush.","ex":{"en":"Have you brushed your teeth?","cn":"你刷牙了吗？"}},{"pos":"VERB 动词","cn":"用刷子在…上涂（或抹）","en":"If you brush something with a liquid, you apply a layer of that liquid using a brush.","ex":{"en":"Take a sheet of filo pastry and brush it with melted butter.","cn":"取一张擀得很薄的油酥面皮，上面刷上一层熔化的牛油。"}},{"pos":"VERB 动词","cn":"拭；拂；擦","en":"If you brush something somewhere, you remove it with quick light movements of your hands.","ex":{"en":"He brushed his hair back with both hands","cn":"他用两手把头发往后捋。"}},{"pos":"V-ERG 及物/不及物动词","cn":"擦过；掠过","en":"If one thing brushes against another or if you brush one thing against another, the first thing touches the second thing lightly while passing it.","ex":{"en":"Something brushed against her leg","cn":"有什么东西扫了一下她的腿。"}},{"pos":"VERB 动词","cn":"（从…身边）擦过，掠过","en":"If you brush past someone or brush by them, you almost touch them as you go past them.","ex":{"en":"My father would burst into the kitchen, brushing past my mother","cn":"我父亲会紧贴着母亲擦身而过，冲进厨房。"}},{"pos":"N-COUNT 可数名词","cn":"小冲突；小争论；小摩擦","en":"If you have a brush with someone, you have an argument or disagreement with them. You use brush when you want to make an argument or disagreement sound less serious than it really is.","ex":{"en":"My first brush with a headmaster came six years ago","cn":"我跟校长的第一次冲突发生在6年前。"}},{"pos":"N-COUNT 可数名词","cn":"触及；碰到；险些遭遇","en":"If you have a brush with a particular situation, usually an unpleasant one, you almost experience it.","ex":{"en":"...the trauma of a brush with death","cn":"和死神擦肩而过的心灵创伤"}},{"pos":"N-UNCOUNT 不可数名词","cn":"灌木区；灌木丛","en":"Brush is an area of rough open land covered with small bushes and trees. You also use brush to refer to the bushes and trees on this land.","ex":{"en":"...the brush fire that destroyed nearly 500 acres.","cn":"焚毁了近500亩灌木丛的大火"}},{"pos":"","cn":"","en":"tarred with the same brush→see: ;"},{"pos":"","cn":"","en":"相关词组：brush aside brush off brush up"}]},"media":{"uk":"media/uk/brush__gb_1.mp3","us":"media/us/brush__us_1.mp3"},"examples":[{"en":"I must brush up on my Spanish before I go to Seville.","cn":"我去塞维利亚之前一定得好好温习我的西班牙语。"},{"en":"Brush the pastry with beaten egg.","cn":"用刷子把打匀的鸡蛋抹在油酥面团上。"}]},"brightly":{"oxford":{"phon":"ˈbraɪtli","pos":"adverb","senses":[{"en":"with a lot of light; with strong light","cn":"明亮地：有很多光；光线强","ex":{"en":"The sun was shining brightly.","cn":"阳光明媚。"}},{"en":"with colours that are strong and easy to see","cn":"鲜艳夺目的","ex":{"en":"The walls were painted brightly.","cn":"墙壁被漆成明亮的颜色。"}},{"en":"in a cheerful and lively way","cn":"快活而生气勃勃的","ex":{"en":"‘Hi!’ she called brightly.","cn":"“嗨！”她轻快地招呼道。"}}]},"media":{"uk":"media/uk/brightly__gb_1.mp3","us":"media/us/brightly__us_1.mp3"},"examples":[{"en":"‘Hi!’ she called brightly.","cn":""},{"en":"‘Hi!’ she called brightly. “","cn":"嗨！”她轻快地招呼道。"}]},"broad":{"media":{"uk":"media/uk/broad__gb_1.mp3","us":"media/us/broad__us_1.mp3"},"oxford":{"phon":"brɔːd","pos":"adjective","senses":[{"en":"wide","cn":"宽阔","sc":"wide","ex":{"en":"a broad street/avenue/river","cn":"宽广的街道／林荫道／河流"}},{"en":"used after a measurement of distance to show how wide something is","cn":"…宽（用于表示距离的量度之后）","sc":"wide","ex":{"en":"two metres broad and one metre high","cn":"两米宽，一米高"}},{"en":"including a great variety of people or things","cn":"涉及各种各样的人（或事物）的；广泛的","sc":"wide range","ex":{"en":"a broad range of products","cn":"各种各样的产品"}},{"en":"general; not detailed","cn":"概括的；一般的；不具体的","g":"[only before noun]","sc":"general","ex":{"en":"the broad outline of a proposal","cn":"提案的纲要"}},{"en":"covering a wide area","cn":"开阔的；辽阔的","sc":"land/water","ex":{"en":"a broad expanse of water","cn":"一片辽阔的水域"}},{"en":"if somebody has a broad accent (= a way of pronouncing the words of a language), you can hear very easily which area they come from","cn":"口音重的；乡音浓的","sc":"accent","ex":{"en":"a broad Yorkshire accent","cn":"很重的约克郡口音。"}},{"en":"if somebody gives a broad hint, they make it very clear what they are thinking or what they want","cn":"明确的；明显的","sc":"hint"},{"en":"dealing with sex in a way that makes people laugh","cn":"粗俗滑稽的；以肉欲作笑料的","lab":"North American English","sc":"humour","ex":{"en":"The movie mixes broad humor with romance.","cn":"那部电影把粗俗幽默和浪漫故事结合在一起。"}},{"en":"an old-fashioned, offensive way of referring to a woman","cn":"（对女人的粗俗称呼）婆娘","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宽的；宽阔的","en":"Something that is broad is wide.","ex":{"en":"His shoulders were broad and his waist narrow","cn":"他细腰宽肩膀。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（笑）咧开嘴的","en":"A broad smile is one in which your mouth is stretched very wide because you are very pleased or amused.","ex":{"en":"He greeted them with a wave and a broad smile.","cn":"他向他们挥一下手，热情地笑着向他们打招呼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"广泛的；涉及面广的","en":"You use broad to describe something that includes a large number of different things or people.","ex":{"en":"A broad range of issues was discussed.","cn":"讨论涉及了范围十分广泛的一系列议题。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（词义或含义）广泛的，概括的","en":"You use broad to describe a word or meaning which covers or refers to a wide range of different things.","ex":{"en":"The term Wissenschaft has a much broader meaning than the English word 'science'.","cn":"Wissenschaft这个术语比英语词science含义更广。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"普遍的；广泛的","en":"You use broad to describe a feeling or opinion that is shared by many people, or by people of many different kinds.","ex":{"en":"The agreement won broad support in the US Congress.","cn":"这一协议在美国国会中赢得了广泛的支持。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（描述或想法）大致的，概括的，笼统的","en":"A broad description or idea is general rather than detailed.","ex":{"en":"These documents provided a broad outline of the Society's development","cn":"这些文件勾画出了社会发展的大致框架。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（暗示）明显的，不掩饰的","en":"A broad hint is a very obvious hint.","ex":{"en":"They've been giving broad hints about what to expect.","cn":"他们对将会出现什么情况已作了明白的暗示。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（口音）浓重的","en":"A broad accent is strong and noticeable.","ex":{"en":"...a Briton who spoke in a broad Yorkshire accent.","cn":"一个讲话带有浓重约克郡口音的英国人"}},{"pos":"N-COUNT 可数名词","cn":"女人，娘们（可能具冒犯意味）","en":"Some men refer to women as broads. This use could cause offence."},{"pos":"","cn":"","en":"in broad daylight→see: ;"}]},"examples":[{"en":"In broad terms , the paper argues that each country should develop its own policy.","cn":"从大体上说，这份报纸认为各国应该建立自己的政策。"},{"en":"The robbery occurred in broad daylight, in a crowded street.","cn":"抢劫就发生在光天化日之下的一条熙熙攘攘的街道上。"}]},"brokerage":{"media":{"uk":"media/uk/brokerage__gb_1.mp3","us":"media/us/brokerage__us_1.mp3"},"oxford":{"phon":"ˈbrəʊkərɪdʒ","pos":"noun","senses":[{"en":"the business of being a broker","cn":"经纪业务","ex":{"en":"a brokerage firm/house","cn":"经纪公司"}},{"en":"an amount of money charged by a broker for work that he/she does","cn":"经纪人佣金（或回扣）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"经纪公司；代理公司","en":"A brokerage or a brokerage firm is a company of brokers.","ex":{"en":"...Japan's four biggest brokerages.","cn":"日本4家最大的代理公司"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（经纪人收取的）佣金，中介费，提成","en":"A brokerage fee or commission is the money charged by a broker for his or her services."}]},"examples":[{"en":"a brokerage firm/house","cn":"经纪公司；经纪行"}]},"bravely":{"oxford":{"phon":"ˈbreɪvli","pos":"adverb","senses":[{"en":"in a way that shows courage","cn":"勇敢地；无畏地；大胆地","ex":{"en":"He fought bravely for his country.","cn":"他为自己的国家勇敢地战斗。"}}]},"media":{"uk":"media/uk/bravely__gb_1.mp3","us":"media/us/bravely__us_1.mp3"},"examples":[{"en":"It was brave of you to speak in front of all those people.","cn":""},{"en":"Today we remember the brave who died in the last war.","cn":""}]},"brilliant":{"media":{"uk":"media/uk/brilliant__gb_1.mp3","us":"media/us/brilliant__us_1.mp3"},"oxford":{"phon":"ˈbrɪliənt","pos":"adjective","senses":[{"en":"extremely clever or impressive","cn":"巧妙的；使人印象深的","ex":{"en":"What a brilliant idea!","cn":"真是个绝妙的主意！"}},{"en":"very good; excellent","cn":"很好的；杰出的","lab":"British English, informal，，","ex":{"en":"‘How was it?’ ‘Brilliant!’","cn":"“怎么样？”“棒极了！”"}},{"en":"very intelligent or showing a lot of skill","cn":"聪颖的；技艺高的","lab":"especially North American English","ex":{"en":"He's a brilliant young scientist.","cn":"他是一个才华横溢的青年科学家。"}},{"en":"very successful","cn":"很成功的","ex":{"en":"a brilliant career","cn":"一帆风顺的事业"}},{"en":"very bright","cn":"明亮的；鲜艳的","ex":{"en":"brilliant sunshine","cn":"明媚的阳光"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"聪颖的；技艺高超的","en":"A brilliant person, idea, or performance is extremely clever or skilful.","ex":{"en":"She had a brilliant mind","cn":"她头脑聪明。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常好的；很棒的；出色的","en":"You can say that something is brilliant when you are very pleased about it or think that it is very good.","ex":{"en":"If you get a chance to see the show, do go — it's brilliant","cn":"如果你有机会去看那个演出，你一定要去——棒极了！"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"成功的；辉煌的","en":"A brilliant career or success is very successful.","ex":{"en":"He served four years in prison, emerging to find his brilliant career in ruins","cn":"他坐了4年牢，出狱后发现自己的辉煌事业已不复存在。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（颜色）鲜明的，绚丽的","en":"A brilliant colour is extremely bright.","ex":{"en":"The woman had brilliant green eyes.","cn":"这个女子有双明亮的碧眼。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（光线等）明亮的，夺目的，灿烂的","en":"You describe light, or something that reflects light, as brilliant when it shines very brightly.","ex":{"en":"The event was held in brilliant sunshine","cn":"这一活动是在阳光明媚的日子举办的。"}}]},"examples":[{"en":"She has one of the most brilliant minds in the country.","cn":"她是全国最有才气的人之一。"},{"en":"The play was a brilliant success.","cn":"那个剧获得了巨大成功。"}]},"brigade":{"oxford":{"phon":"brɪˈɡeɪd","pos":"noun","senses":[{"en":"a large group of soldiers that forms a unit of an army","cn":"旅（陆军编制单位）","ex":{"en":"A special army brigade is to be formed.","cn":"一个特种陆军旅即将成立。"}},{"en":"used, always with a word or phrase in front of it, to describe a group of people who share the same opinions or are similar in some other way","cn":"（主张相同或其他某方面相似的）伙，帮，派","g":"[usually singular]","lab":"often disapproving","ex":{"en":"the anti-smoking brigade","cn":"反吸烟派"}}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"旅","en":"A brigade is one of the groups which an army is divided into.","ex":{"en":"...the men of the Seventh Armoured Brigade.","cn":"第七装甲旅的士兵们"}},{"pos":"N-SING 单数名词","cn":"（信奉某事或具有共同特点的）一帮人，族","en":"You can use brigade to refer to a group of people who believe strongly in a particular thing or who share a particular characteristic.","ex":{"en":"...the healthy eating brigade.","cn":"健康饮食族"}}]},"media":{"uk":"media/uk/brigade__gb_1.mp3","us":"media/us/brigade__us_1.mp3"},"examples":[{"en":"the anti-smoking brigade","cn":"反吸烟派"},{"en":"Snowmobile brigades delivered food and medicine.","cn":"雪地车车队送来了食物和药品。"}]},"brushes":{"lemma":"brush","media":{"img":["media/ldoce/img/brushes.jpg"]}},"bruised":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to damage part of your body, or someone else’s body","cn":""},{"en":"to hurt yourself quite severely, or to be hurt in an accident or fighting","cn":""}]},"examples":[{"en":"She fell off her bike and bruised her knee.","cn":"","src":"ld"},{"en":"The incident had bruised his pride.","cn":"","src":"ld"}],"media":{"uk":"media/uk/bruised__gb_1.mp3","us":"media/us/bruised__us_1.mp3"},"oxford":{"phon":"bruːzd","pos":"adjective","senses":[{"en":"having one or more blue, brown or purple marks on your skin after falling, being hit, etc.","cn":"青肿；瘀伤；碰伤","ex":{"en":"He suffered badly bruised ribs in the crash.","cn":"他在车祸中肋骨严重撞伤。"}},{"en":"having marks on them where they have been damaged","cn":"瘀伤：在受损的地方留下痕迹","ex":{"en":"a tray of slightly bruised apples","cn":"一盘稍微碰伤的苹果"}},{"en":"badly affected by something and feeling unhappy and less confident because of it","cn":"瘀伤：受某物的影响严重，并因此而感到不开心和不自信","ex":{"en":"a bruised ego","cn":"受伤的自尊心"}}]},"base":"bruise"},"breathing":{"media":{"uk":"media/uk/breathing__gb_1.mp3","us":"media/us/breathing__us_1.mp3"},"oxford":{"phon":"ˈbriːðɪŋ","pos":"noun","senses":[{"en":"the action of taking air into the lungs and sending it out again","cn":"呼吸","ex":{"en":"Her breathing became steady and she fell asleep.","cn":"她的呼吸变得均匀，然后睡着了。"}}]},"examples":[{"en":"Heavy (= loud) breathing was all I could hear.","cn":"我所能听到的只有沉重的呼吸声。"},{"en":"Her breathing became steady and she fell asleep.","cn":"她的呼吸变得均匀，便睡着了。"}]},"branch":{"oxford":{"phon":"brɑːntʃ","pos":"noun","senses":[{"en":"a part of a tree that grows out from the main stem and on which leaves, flowers and fruit grow","cn":"树枝","sc":"of tree","ex":{"en":"She climbed the tree and hid in the branches.","cn":"她爬上树，躲在树枝里。"}},{"en":"a local office or shop belonging to a large company or organization","cn":"分支；分部；分行；分店","sc":"of company","ex":{"en":"The bank has branches all over the country.","cn":"那家银行在全国各地设有分行。"}},{"en":"a part of a government or other large organization that deals with one particular aspect of its work","cn":"政府部门；分支机构","sc":"of government","ex":{"en":"Scotland Yard's anti-terrorist branch swung into action.","cn":"苏格兰场的反恐部门立即行动起来。"}},{"en":"a division of an area of knowledge or a group of languages","cn":"（学科及语言的）分支","sc":"of knowledge","ex":{"en":"the branch of computer science known as ‘artificial intelligence’","cn":"计算机科学中的所谓“人工智能”分科"}},{"en":"a smaller or less important part of a river, road, railway, etc. that leads away from the main part","cn":"支流；支路；支线","sc":"of river/road","ex":{"en":"a branch of the Rhine","cn":"莱茵河的支流"}},{"en":"a group of members of a family who all have the same ancestors","cn":"家族分支","sc":"of family","ex":{"en":"My uncle's branch of the family emigrated to Canada.","cn":"我们家族中我叔父的这一支移居到了加拿大。"}},{"en":"to divide into two or more parts, especially smaller or less important parts","cn":"分开；分岔","ex":{"en":"The accident happened where the road branches.","cn":"事故发生在岔道处。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"树枝","en":"The branches of a tree are the parts that grow out from its trunk and have leaves, flowers, or fruit growing on them."},{"pos":"N-COUNT 可数名词","cn":"（企业或组织的）分支机构，分部，分店","en":"A branch of a business or other organization is one of the offices, shops, or groups which belong to it and which are located in different places.","ex":{"en":"The local branch of Bank of America is handling the accounts","cn":"美国银行在当地的分行正在处理这些账目。"}},{"pos":"N-COUNT 可数名词","cn":"(政府或公安机关等的）部门，机构","en":"A branch of an organization such as the government or the police force is a department that has a particular function.","ex":{"en":"Senate employees could take their employment grievances to another branch of government","cn":"参议院的雇员可以向别的政府部门申诉工作问题。"}},{"pos":"N-COUNT 可数名词","cn":"（某学科的）分支，分科","en":"A branch of a subject is a part or type of it.","ex":{"en":"Whole branches of science may not receive any grants.","cn":"各自然科学学科可能都得不到任何拨款。"}},{"pos":"N-COUNT 可数名词","cn":"（家族的）分支，支系，旁系","en":"A branch of your family is a group of its members who are descended from one particular person.","ex":{"en":"This is one of the branches of the Roosevelt family.","cn":"这是罗斯福家族的一个支系。"}},{"pos":"","cn":"","en":"相关词组：branch off branch out"}]},"media":{"uk":"media/uk/branch__gb_1.mp3","us":"media/us/branch__us_1.mp3","img":["media/ldoce/img/tree.jpg"]},"examples":[{"en":"My uncle's branch of the family emigrated to Canada.","cn":"我们家族中我叔父的这一支移居到了加拿大。"},{"en":"the branch of computer science known as ‘artificial intelligence’","cn":"计算机科学中的所谓“人工智能”分科"}]},"broke":{"media":{"uk":"media/uk/broke__gb_1.mp3","us":"media/us/broke__us_1.mp3"},"oxford":{"phon":"brəʊk","pos":"adjective","senses":[{"en":"having no money","cn":"没钱；不名一文","ex":{"en":"I'm always broke by the end of the month.","cn":"我总是一到月底就没钱花了。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Broke is the past tense of break ."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"身无分文的；一文不名的","en":"If you are broke, you have no money.","ex":{"en":"What do you mean, I've got enough money? I'm as broke as you are.","cn":"你是什么意思，我的钱还富余吗？我已和你一样分文不剩了。"}},{"pos":"PHRASE 短语","cn":"破产","en":"If a company or person goes broke, they lose money and are unable to continue in business or to pay their debts.","ex":{"en":"Balton went broke twice in his career.","cn":"巴尔顿一生中经历了两次破产。"}},{"pos":"PHRASE 短语","cn":"孤注一掷","en":"If you go for broke, you take the most extreme or risky of the possible courses of action in order to try and achieve success.","ex":{"en":"It was a sharp disagreement about whether to go for broke or whether to compromise.","cn":"是放手一搏还是保守妥协，在这一问题上的分歧很尖锐。"}}]},"examples":[{"en":"During the recession thousands of small businesses went broke (= had to stop doing business).","cn":"经济衰退期间成千上万家小企业被迫关门了。"},{"en":"I'm always broke by the end of the month.","cn":"我总是一到月底就没钱花了。"}],"base":"break"},"brisk":{"media":{"uk":"media/uk/brisk__gb_1.mp3","us":"media/us/brisk__us_1.mp3"},"oxford":{"phon":"brɪsk","pos":"adjective","senses":[{"en":"quick; busy","cn":"快的；敏捷的；忙碌的","ex":{"en":"a brisk walk","cn":"轻盈的步履"}},{"en":"practical and confident; showing a desire to get things done quickly","cn":"现实自信的；麻利的","ex":{"en":"His tone became brisk and businesslike.","cn":"他的语气变得自信干练而务实。"}},{"en":"cold but pleasantly fresh","cn":"凉爽的；清新的","ex":{"en":"a brisk wind/breeze","cn":"凉爽的风／微风"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"轻快的；生气勃勃的","en":"A brisk activity or action is done quickly and in an energetic way.","ex":{"en":"Taking a brisk walk can often induce a feeling of well-being","cn":"快步行走常常会使人感到身心舒畅。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（生意）兴隆的，红火的","en":"If trade or business is brisk, things are being sold very quickly and a lot of money is being made.","ex":{"en":"Vendors were doing a brisk trade in souvenirs","cn":"商贩们的纪念品生意很红火。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天气）寒冷而清新的","en":"If the weather is brisk, it is cold and fresh.","ex":{"en":"...a typically brisk winter's day on the South Coast","cn":"南部海岸一个典型的清冷冬日"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"爽快干脆的；精干利落的；麻利的","en":"Someone who is brisk behaves in a busy, confident way which shows that they want to get things done quickly.","ex":{"en":"The Chief summoned me downstairs. He was brisk and businesslike","cn":"主管叫我到楼下。他做事干练、务实。"}}]},"examples":[{"en":"His tone became brisk and businesslike.","cn":"他的语气变得自信干练而务实。"},{"en":"Ice-cream vendors were doing a brisk trade (= selling a lot of ice cream).","cn":"冰淇淋小贩的生意很红火。"}]},"bridges":{"lemma":"bridge","media":{"img":["media/pic/bridge_senses.jpg","media/thumb/bridge.jpg"],"uk":"media/uk/bridge__gb_1.mp3","us":"media/us/bridge__us_1.mp3"}},"brain":{"media":{"uk":"media/uk/brain__gb_1.mp3","us":"media/us/brain__us_1.mp3","img":["media/ldoce/img/body.jpg"]},"oxford":{"phon":"breɪn","pos":"noun","senses":[{"en":"the organ inside the head that controls movement, thought, memory and feeling","cn":"脑","g":"[countable]","sc":"in head","ex":{"en":"The human brain is a complex organ.","cn":"人脑是一个复杂的器官。"}},{"en":"the brain of an animal, eaten as food","cn":"（供食用的）动物脑髓","g":"[plural]","sc":"food","ex":{"en":"sheep’s brains","cn":"羊脑"}},{"en":"the ability to learn quickly and think about things in a logical and intelligent way","cn":"智力；脑力；逻辑思维能力","g":"[uncountable, countable, usually plural]","sc":"intelligence","ex":{"en":"It doesn't take much brain to work out that both stories can't be true.","cn":"不必费多大脑筋就知道，两种说法不可能都是真的。"}},{"en":"an intelligent person","cn":"聪明的人；有智慧的人","g":"[countable, usually plural]","lab":"informal","sc":"intelligent person","ex":{"en":"one of the best scientific brains in the country","cn":"国家最优秀的科技人才之一"}},{"en":"the most intelligent person in a particular group; the person who is responsible for thinking of and organizing something","cn":"（群体中）最聪明的人；策划组织者","g":"[singular]","sc":"intelligent person","ex":{"en":"He's always been the brains of the family.","cn":"这家人数他聪明。"}},{"en":"to kill a person or an animal by hitting them very hard on the head","cn":"猛击…的脑袋致死","ex":{"en":"I nearly brained myself on that low beam.","cn":"那根低横梁差点儿把我撞死。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"脑；大脑","en":"Your brain is the organ inside your head that controls your body's activities and enables you to think and to feel things such as heat and pain.","ex":{"en":"Her father died of a brain tumour.","cn":"她父亲死于脑瘤。"}},{"pos":"N-COUNT 可数名词","cn":"头脑；智力","en":"Your brain is your mind and the way that you think.","ex":{"en":"Once you stop using your brain you soon go stale","cn":"一旦停止用脑，人很快就会变得迟钝。"}},{"pos":"N-COUNT 可数名词","cn":"智力；智慧；头脑","en":"If someone has brains or a good brain, they have the ability to learn and understand things quickly, to solve problems, and to make good decisions.","ex":{"en":"They were not the only ones to have brains and ambition","cn":"并不是只有他们聪明、有志向。"}},{"pos":"N-COUNT 可数名词","cn":"智囊；出谋划策者","en":"If someone is the brains behind an idea or an organization, he or she had that idea or makes the important decisions about how that organization is managed.","ex":{"en":"Mr White was the brains behind the scheme","cn":"怀特先生是该项计划的幕后策划者。"}},{"pos":"VERB 动词","cn":"猛击…的头部","en":"To brain someone means to hit them forcefully on the head.","ex":{"en":"He had threatened to brain him then and there.","cn":"他当时就威胁要打爆他的脑袋。"}},{"pos":"PHRASE 短语","cn":"把…的脑袋打伤；把…脑袋打开花","en":"To beat someone's brains out or bash their brains in means to hit their head very hard, so that they are badly injured or killed.","ex":{"en":"They stood over him with clubs raised as if to beat his brains out.","cn":"他们举着棍子监视着他，好像要揍扁他的脑袋。"}},{"pos":"PHRASE 短语","cn":"（用枪）把…的脑袋打开花；射中…的头部","en":"To blow someone's brains out means to shoot them in the head, killing them.","ex":{"en":"Give me all your money or I'll blow your brains out","cn":"把你所有的钱都给我，否则我就一枪把你的脑袋打开花。"}},{"pos":"PHRASE 短语","cn":"一直想着；对…念念不忘","en":"If someone has something on the brain, they keep thinking about it.","ex":{"en":"You've had chess on the brain since you were little.","cn":"你从很小的时候就对下棋产生了浓厚兴趣。"}},{"pos":"PHRASE 短语","cn":"请教；讨教","en":"If you pick someone's brains, you ask them to help you with a problem because they know more about the subject than you.","ex":{"en":"Why should a successful company allow another firm to pick its brains?","cn":"为什么一个成功的企业就得允许别的公司来讨教呢？"}},{"pos":"","cn":"","en":"to rack your brains→see: ;"}]},"examples":[{"en":"It doesn't take much brain to work out that both stories can't be true.","cn":"不必费多大脑筋就知道，两种说法都不可能是真的。"},{"en":"The band's drummer is the brains behind their latest venture.","cn":"这位乐队鼓手是他们最近一次活动的策划人。"}]},"bride":{"media":{"uk":"media/uk/bride__gb_1.mp3","us":"media/us/bride__us_1.mp3","img":["media/ldoce/img/bride.jpg"]},"oxford":{"phon":"braɪd","pos":"noun","senses":[{"en":"a woman on her wedding day, or just before or just after it","cn":"新娘；即将（或刚刚）结婚的女子","ex":{"en":"a toast to the bride and groom","cn":"向新娘新郎祝酒"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"新娘","en":"A bride is a woman who is getting married or who has just got married."}]},"examples":[{"en":"He introduced his new bride.","cn":"他介绍了他的新娘。"},{"en":"a toast to the bride and groom","cn":"向新娘新郎祝酒"}]},"broom":{"media":{"img":["media/pic/cleaning_comp.jpg","media/thumb/broom.jpg"],"uk":"media/uk/broom__gb_1.mp3","us":"media/us/broom__us_1.mp3"},"oxford":{"phon":"bruːm","pos":"noun","senses":[{"en":"a brush on the end of a long handle, used for sweeping floors","cn":"扫把；扫帚","g":"[countable]","ex":{"en":"Grab a broom and let’s clean up.","cn":"拿起扫帚，我们来大扫除吧。"}},{"en":"a wild bush with small yellow flowers","cn":"金雀花（野生灌木，开小黄花）","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"扫帚","en":"A broom is a kind of brush with a long handle. You use a broom for sweeping the floor."},{"pos":"N-UNCOUNT 不可数名词","cn":"金雀花（一种野生灌木，开许多黄色小花）","en":"Broom is a wild bush with a lot of tiny yellow flowers."}]}},"breakfast":{"media":{"uk":"media/uk/breakfast__gb_1.mp3","us":"media/us/breakfast__us_1.mp3"},"oxford":{"phon":"ˈbrekfəst","pos":"noun","senses":[{"en":"the first meal of the day","cn":"早餐；早饭","lab":"especially British English","ex":{"en":"They were having breakfast when I arrived.","cn":"我到达时他们正在吃早饭。"}},{"en":"to eat breakfast","cn":"吃早饭；用早餐","ex":{"en":"Many of the hotel’s guests had already breakfasted and departed.","cn":"酒店的许多客人已经吃过早餐并离开了。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"早餐；早饭","en":"Breakfast is the first meal of the day. It is usually eaten in the early part of the morning.","ex":{"en":"What's for breakfast?","cn":"早餐吃什么？"}},{"pos":"N-COUNT 可数名词","cn":"（咸肉、蛋类等）熟食早餐","en":"A cooked breakfast or a hot breakfast is a breakfast that consists of cooked food, such as bacon and eggs."},{"pos":"VERB 动词","cn":"吃早饭","en":"When you breakfast, you have breakfast. →see usage note at:","ex":{"en":"All the ladies breakfasted in their rooms.","cn":"所有女士都在她们的房间里吃早餐。"}}]},"examples":[{"en":"Do you want bacon and eggs for breakfast?","cn":"你早饭要吃熏咸肉和鸡蛋吗？"},{"en":"They were having breakfast when I arrived.","cn":"我到达时他们正在吃早饭。"}]},"brushing":{"lemma":"brush"},"brakes":{"lemma":"brake"},"broader":{"lemma":"broad"},"breaches":{"lemma":"breach"},"bristled":{"oxford":{"phon":"ˈbrɪsl","pos":"noun","senses":[{"en":"a short stiff hair","cn":"短而硬的毛发；刚毛"},{"en":"one of the short stiff hairs or wires in a brush","cn":"刷子毛"}]}},"brooms":{"lemma":"broom"},"bringing":{"lemma":"bring"},"brighter":{"lemma":"bright"},"brains":{"lemma":"brain"},"brewing":{"oxford":{"phon":"bruː","pos":"verb","senses":[{"en":"to make beer","cn":"酿制（啤酒）"},{"en":"to make a hot drink of tea or coffee","cn":"沏（茶）；煮（咖啡）"}]}},"brits":{"oxford":{"phon":"brɪt","pos":"noun","senses":[{"en":"a person from Britain","cn":"英国人"}]}},"breaking":{"lemma":"break"},"brownies":{"oxford":{"phon":"ˈbraʊni","pos":"noun","senses":[{"en":"a thick soft flat cake made with chocolate and sometimes nuts and served in small squares","cn":"巧克力方块蛋糕（有时放有坚果）"},{"en":"a branch of the Scout Association for girls between the ages of seven and ten or eleven","cn":"幼女童军（由 7 到 10 或 11 岁的女孩组成）"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld5_brownies_the.mp3","us":"media/ldoce/hwd/ame/e/ld5_brownies_the.mp3"}},"brothers":{"lemma":"brother"},"broadened":{"oxford":{"phon":"ˈbrɔːdn","pos":"verb","senses":[{"en":"to become wider","cn":"变宽；变阔"},{"en":"to affect or make sth affect more people or things （","cn":"使）扩大影响"}]}},"breakfasted":{"lemma":"breakfast"},"britons":{"oxford":{"phon":"ˈbrɪtn","pos":"noun","senses":[{"en":"a person from Britain","cn":"英国人"}]}},"breached":{"lemma":"breach"},"breaching":{"lemma":"breach"},"breaks":{"lemma":"break"},"brings":{"lemma":"bring"},"breakdowns":{"lemma":"breakdown"},"bribe":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"贿赂","en":"A bribe is a sum of money or something valuable that one person offers or gives to another in order to persuade him or her to do something.","ex":{"en":"He was being investigated for receiving bribes.","cn":"他因收受贿赂正在接受调查。"}},{"pos":"VERB 动词","cn":"向…行贿","en":"If one person bribes another, they give them a bribe.","ex":{"en":"He was accused of bribing a senior bank official","cn":"他被指控贿赂一名高级银行官员。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to give money to someone in an official position, in order to persuade them to do something that they should not do","cn":""},{"en":"a large amount of money paid to someone in a high position in a company or government, for arranging a business deal for you","cn":""},{"en":"a small amount of money paid to someone to persuade them to do something that is dishonest but usually not very serious","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"You pay a bribe to get someone to do something they wouldn't do otherwise. It's usually dishonest and often criminal."}]},"collocations":{"phrases":["VERB + BRIBE give sb, offer (sb), pay sb He admitted paying bribes to police officers. | accept, take","PREP. in ~s He paid out millions of dollars in bribes. | ~ of a bribe of &pound; 200"]},"media":{"uk":"media/ldoce/hwd/bre/1/bribe_n0205.mp3","us":"media/ldoce/hwd/ame/1/bribe1.mp3"},"examples":[{"en":"She had been offered a $50 000 bribe to drop the charges.","cn":"有人用 5 万元贿赂她，要她撤回控告。"},{"en":"It was alleged that he had taken bribes while in office.","cn":"他被指称在任时收受贿赂。"}],"oxford":{"phon":"braɪb","pos":"noun","senses":[{"en":"a sum of money or something valuable that you give or offer to somebody to persuade them to help you, especially by doing something dishonest","cn":"贿赂","lab":"British English","ex":{"en":"It was alleged that he had taken bribes while in office.","cn":"他被指在任时收受贿赂。"}},{"en":"to give somebody money or something valuable in order to persuade them to help you, especially by doing something dishonest","cn":"向（某人）行贿；贿赂","ex":{"en":"They bribed the guards with cigarettes.","cn":"他们用香烟贿赂看守。"},"pos":"verb"}]}},"bruise":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"淤伤；青肿","en":"A bruise is an injury which appears as a purple mark on your body, although the skin is not broken.","ex":{"en":"How did you get that bruise on your cheek?","cn":"你脸上的淤伤是怎么搞的？"}},{"pos":"V-ERG 及物/不及物动词","cn":"碰伤；擦伤","en":"If you bruise a part of your body, a bruise appears on it, for example because something hits you. If you bruise easily, bruises appear when something hits you only slightly.","ex":{"en":"I had only bruised my knee","cn":"我只是把膝盖给碰伤了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(将)(蔬菜、水果或植物）碰伤","en":"If a fruit, vegetable, or plant bruises or is bruised, it is damaged by being handled roughly, making a mark on the skin.","ex":{"en":"Choose a warm, dry day to cut them off the plants, being careful not to bruise them.","cn":"选一个干燥暖和的日子把它们从植株上割下来，注意不要碰伤它们。"}},{"pos":"VERB 动词","cn":"挫伤；伤害","en":"If you are bruised by an unpleasant experience, it makes you feel unhappy or upset.","ex":{"en":"The government will be severely bruised by yesterday's events.","cn":"昨天的事件将会让政府严重受挫。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"damage to part of your body caused by an accident or an attack","cn":""},{"en":"an injury, especially a deep cut in your skin made by a knife, bullet, or bomb","cn":""},{"en":"a small injury made when a sharp object cuts your skin","cn":""}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"If you're just learning to skateboard, you’ve probably got an ugly bruise or two to show for it — those purple and yellow patches you get on your skin where you’ve bumped and scraped, and they probably hurt, too."}]},"collocations":{"phrases":["ADJ. black, dark, livid, purple | swollen","VERB + BRUISE suffer She suffered only minor cuts and bruises.","BRUISE + VERB form A bruise had formed below his left eye. | fade"]},"media":{"uk":"media/ldoce/hwd/bre/5/bruise_n0205.mp3","us":"media/ldoce/hwd/ame/e/bruise1.mp3"},"examples":[{"en":"They had been badly bruised by the defeat.","cn":"失败使他们的自信心大为受挫。"},{"en":"She had slipped and badly bruised her face.","cn":"她滑了一跤，摔得鼻青脸肿。"}],"oxford":{"phon":"bruːz","pos":"noun","senses":[{"en":"a blue, brown or purple mark that appears on the skin after somebody has fallen, been hit, etc.","cn":"青肿；瘀伤；碰伤","ex":{"en":"His legs were covered in bruises.","cn":"他腿上布满了瘀伤。"}},{"en":"a mark on a fruit or vegetable where it is damaged","cn":"（水果或蔬菜的）碰伤，伤痕"},{"en":"to develop a bruise, or make a bruise or bruises appear on the skin of somebody/something","cn":"（使）出现伤痕；撞伤；擦伤","g":"[intransitive, transitive]","lab":"especially British English","ex":{"en":"Strawberries bruise easily.","cn":"草莓容易碰伤。"},"pos":"verb"},{"en":"to affect somebody badly and make them feel unhappy and less confident","cn":"打击；挫伤","g":"[transitive, usually passive]","ex":{"en":"They had been badly bruised by the defeat.","cn":"失败使他们的自信心大为受挫。"},"pos":"verb"}]}},"bravery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"勇敢；勇气；无畏精神","en":"Bravery is brave behaviour or the quality of being brave.","ex":{"en":"He deserves the highest praise for his bravery.","cn":"他的英勇行为应该获得最高的赞誉。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the quality of being brave when you are facing a difficult or dangerous situation, or when you are very ill","cn":""},{"en":"courage in a dangerous or frightening situation, especially when you are fighting in a war","cn":""},{"en":"the courage and determination to do something difficult or unpleasant","cn":""}]},"collocations":{"phrases":["ADJ. great, outstanding","VERB + BRAVERY demonstrate, display, show","BRAVERY + NOUN award, medal","PREP. with ~ The men fought with great bravery.","PHRASES an act of bravery"]},"media":{"uk":"media/ldoce/hwd/bre/4/bravery0205.mp3","us":"media/ldoce/hwd/ame/f/laadbravery.mp3"},"examples":[{"en":"acts of skill and bravery","cn":"有勇有谋的行为"},{"en":"an award for outstanding bravery","cn":"杰出英勇奖"}],"oxford":{"phon":"ˈbreɪvəri","pos":"noun","senses":[{"en":"the quality of being brave","cn":"勇敢；勇敢的行为","ex":{"en":"an award for outstanding bravery","cn":"杰出英勇奖"}}]}},"brigadier":{"collins":{"senses":[{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"（英国）准将","en":"A brigadier is a senior officer in the British armed forces who is in charge of a brigade and has the rank above colonel and below major general."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a high military rank in the British army, or the person who has this rank 〔","cn":"英国陆军的〕准将"}]},"media":{"uk":"media/ldoce/hwd/bre/e/brigadier0205.mp3","us":"media/ldoce/hwd/ame/9/brigadier.mp3"},"examples":[{"en":"Brigadier Michael Swift","cn":"迈克尔 · 斯威夫特准将"}],"oxford":{"phon":"ˌbrɪɡəˈdɪə(r)","pos":"noun","senses":[{"en":"an officer of high rank in the British army","cn":"（英国陆军）准将，旅长","ex":{"en":"Brigadier Michael Swift","cn":"迈克尔·斯威夫特准将"}}]}},"brandy":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"白兰地（一种烈性酒，常在饭后饮用）","en":"Brandy is a strong alcoholic drink. It is often drunk after a meal."},{"pos":"N-COUNT 可数名词","cn":"一杯白兰地","en":"A brandy is a glass of brandy.","ex":{"en":"After a couple of brandies Michael started telling me his life story.","cn":"喝了两杯白兰地后，迈克尔开始向我讲述他的生平。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong alcoholic drink made from wine, or a glass of this drink （","cn":"一杯）白兰地（酒）"}]},"collocations":{"phrases":["ADJ. double, large | single, small | stiff a stiff brandy and soda (= containing a lot of brandy and not much soda) | straight | cherry, plu","QUANT. dash, drop, nip He added a dash of brandy to his coffee. | measure, shot, tot She poured herself a large measure of brandy. | bottle,","VERB + BRANDY drink Do you drink brandy? | have I'll have some brandy, please. | pour (sb) | sip | gulp, swig | down, finish | distil, produ","BRANDY + NOUN bottle | balloon (= a kind of glass), glass He sat cradling his brandy glass."]},"media":{"uk":"media/ldoce/hwd/bre/0/brandy0205.mp3","us":"media/ldoce/hwd/ame/9/brandy.mp3"},"oxford":{"phon":"ˈbrændi","pos":"noun","senses":[{"en":"a strong alcoholic drink made from wine","cn":"白兰地（酒）","g":"[uncountable, countable]","ex":{"en":"a bottle of brandy","cn":"一瓶白兰地"}},{"en":"a glass of brandy","cn":"一杯白兰地","g":"[countable]","ex":{"en":"a brandy and soda","cn":"白兰地和苏打水"}}]}},"bribery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"贿赂行为；行贿","en":"Bribery is the act of offering someone money or something valuable in order to persuade them to do something for you.","ex":{"en":"He was jailed on charges of bribery.","cn":"他因受到行贿指控而被捕入狱。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"dishonest behaviour","cn":""},{"en":"when someone who works for the government, the police etc uses their power dishonestly to get money or gain an advantage","cn":""},{"en":"when someone offers money to a politician or government official in order to persuade them to do something","cn":""}]},"collocations":{"phrases":["ADJ. political","VERB + BRIBERY resort to","BRIBERY + NOUN scandal","PHRASES bribery and corruption The charge in the present case is one of bribery and corruption. • Note at CRIME (for more verbs)"]},"media":{"uk":"media/ldoce/hwd/bre/d/bribery0205.mp3","us":"media/ldoce/hwd/ame/7/bribery.mp3"},"examples":[{"en":"She was arrested on bribery charges.","cn":"她因被控贿赂罪而遭逮捕。"},{"en":"allegations of bribery and corruption","cn":"有关贿赂和贪污的指控"}],"oxford":{"phon":"ˈbraɪbəri","pos":"noun","senses":[{"en":"the giving or taking of bribes","cn":"行贿；受贿；贿赂","ex":{"en":"She was arrested on bribery charges.","cn":"她因被控贿赂罪而遭逮捕。"}}]}},"bravado":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"虚张声势；逞能；逞强","en":"Bravado is an appearance of courage or confidence that someone shows in order to impress other people.","ex":{"en":"'You won't get away with this,' he said with unexpected bravado.","cn":"“这事你休想就这么过去，”他以出人意料的强横语气说道。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"behaviour that is deliberately intended to make other people believe you are brave and confident","cn":"逞能﹐逞强行为﹐虚张声势"}]},"vocab":{"pos":"n","senses":[{"en":"If you act with bravado , you are making a bold showy statement. Picture a cowboy bursting through saloon doors in an old western, and you can picture bravado ."}]},"collocations":{"phrases":["ADJ. sheer | mere | false, forced","PREP. out of ~ He behaved aggressively out of bravado. | with ~ &lsquo;I'll be fine on my own,&rsquo; she said with bravado.","PHRASES a display/show of bravado"]},"media":{"uk":"media/ldoce/hwd/bre/f/bravado0205.mp3","us":"media/ldoce/hwd/ame/a/bravado.mp3"},"examples":[{"en":"an act of sheer bravado","cn":"纯属逞能的举动"},{"en":"youthful bravado","cn":"年轻人的逞强行为"}],"oxford":{"phon":"brəˈvɑːdəʊ","pos":"noun","senses":[{"en":"a confident way of behaving that is intended to impress people, sometimes as a way of hiding a lack of confidence","cn":"逞能；逞强；（有时）虚张声势","ex":{"en":"an act of sheer bravado","cn":"纯属逞能的举动"}}]}},"breather":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"短暂休息","en":"If you take a breather, you stop what you are doing for a short time and have a rest.","ex":{"en":"Relax and take a breather whenever you feel that you need one.","cn":"要放松，什么时候觉得需要休息就休息一下。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to stop working for a while in order to rest, eat etc","cn":""},{"en":"to stop for a while in order to rest","cn":""},{"en":"to stop for a while because you want a rest, especially because you have been doing something very difficult or tiring","cn":""}]},"collocations":{"phrases":["ADJ. quick, short, slight","VERB + BREATHER have, stop for, take | enjoy | give sb The weekend will give me a slight breather to finish this work in."]},"media":{"uk":"media/ldoce/hwd/bre/f/breather0205.mp3","us":"media/ldoce/hwd/ame/3/breather.mp3"},"examples":[{"en":"Tell me when you need a breather.","cn":"你需要休息时就告诉我。"},{"en":"a five-minute breather","cn":"休息五分钟"}],"oxford":{"phon":"ˈbriːðə(r)","pos":"noun","senses":[{"en":"a short break for rest or to relax","cn":"短暂的休息","ex":{"en":"to take/have a breather","cn":"歇一下"}}]}},"breezy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"随意的；乐天的；自信的","en":"If you describe someone as breezy, you mean that they behave in a casual, cheerful, and confident manner.","ex":{"en":"...his bright and breezy personality","cn":"他开朗活泼的个性"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明快的；生动的；活泼的","en":"If you describe something as breezy, especially music or clothing, you mean that it is bright, lively, and cheerful.","ex":{"en":"This album is bright, breezy and playful.","cn":"这张专辑音乐轻松明快，趣味十足。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（天气）有微风的","en":"When the weather is breezy, there is a fairly strong but pleasant wind blowing.","ex":{"en":"The day was breezy and warm.","cn":"这一天微风习习，暖洋洋的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if it is windy, there is a lot of wind","cn":""},{"en":"blustery weather is very windy, with sudden strong winds","cn":""},{"en":"if the weather is breezy, the wind blows fairly strongly","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. very | a little, slightly It's a little breezy up here.","PHRASES bright and breezy The weather at the seaside was ideal?bright and breezy. 2 cheerful and relaxed","VERBS be, seem, sound She tried to sound breezy on the phone.","PHRASES bright and breezy His bright and breezy manner sometimes irritated people."]},"media":{"uk":"media/ldoce/hwd/bre/b/breezy0205.mp3","us":"media/ldoce/hwd/ame/c/breezy.mp3"},"examples":[{"en":"‘Hi folks,’ he said breezily. “","cn":"嗨，诸位。”他快活地说。"},{"en":"You're very bright and breezy today!","cn":"你今天精神焕发！"}],"oxford":{"phon":"ˈbriːzi","pos":"adjective","senses":[{"en":"with the wind blowing quite strongly","cn":"通风良好的；有微风的","ex":{"en":"It was a bright, breezy day.","cn":"那天和风丽日。"}},{"en":"having or showing a cheerful and relaxed manner","cn":"轻松愉快的","ex":{"en":"You're very bright and breezy today!","cn":"你今天精神焕发！"}}]}},"brighten":{"collins":{"senses":[{"pos":"VERB 动词","cn":"开颜；露出喜色；快乐起来","en":"If someone brightens or their face brightens, they suddenly look happier.","ex":{"en":"Seeing him, she seemed to brighten a little","cn":"看到他后，她似乎露出点儿喜色。"}},{"pos":"VERB 动词","cn":"（眼睛）发亮，放光","en":"If your eyes brighten, you suddenly look interested or excited.","ex":{"en":"His eyes brightened and he laughed","cn":"他眼睛一亮，笑了起来"}},{"pos":"VERB 动词","cn":"使生色；为…增辉添彩","en":"If someone or something brightens a place, they make it more colourful and attractive.","ex":{"en":"Tubs planted with wallflowers brightened the area outside the door.","cn":"桂竹香盆栽为门外的景致增色不少。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）好转；（使）变得乐观","en":"If someone or something brightens a situation or the situation brightens, it becomes more pleasant, enjoyable, or favourable.","ex":{"en":"That does not do much to brighten the prospects of kids in the city","cn":"那并不能使城里孩子们的前途更光明些。"}},{"pos":"V-ERG 及物/不及物动词","cn":"照亮；（使）变明亮","en":"When a light brightens a place or when a place brightens, it becomes brighter or lighter.","ex":{"en":"The sky above the ridge of mountains brightened","cn":"山脊上方的天空变得明亮起来。"}},{"pos":"VERB 动词","cn":"（天气）放晴","en":"If the weather brightens, it becomes less cloudy or rainy, and the sun starts to shine.","ex":{"en":"By early afternoon the weather had brightened.","cn":"中午刚过，天就放晴了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to start to look happy again","cn":""},{"en":"to start to feel a little more happy","cn":""},{"en":"to feel happier and more hopeful, especially because you have received some good news, or have seen or thought something encouraging","cn":""}]},"collocations":{"phrases":["ADV. considerably | a bit, a little | visibly Their rather heavy faces brightened visibly. | suddenly | up She brightened up a bit at the th"]},"media":{"uk":"media/ldoce/hwd/bre/b/brighten0205.mp3","us":"media/ldoce/hwd/ame/d/brighten.mp3"},"examples":[{"en":"A personal letter will usually brighten up a person's day.","cn":"一封私人来信往往就能使人一天心情愉快。"},{"en":"Fresh flowers will brighten up any room in the house.","cn":"鲜花会使屋里的任何房间都亮丽生色。"}],"oxford":{"phon":"ˈbraɪtn","pos":"verb","senses":[{"en":"to become or make something lighter or brighter in colour","cn":"（使）明亮，色彩鲜艳","g":"[intransitive, transitive]","ex":{"en":"In the distance, the sky was beginning to brighten.","cn":"远方的天空开始泛白。"}},{"en":"to become, feel or look happier; to make somebody look happier","cn":"（使）快活起来","g":"[intransitive, transitive]","ex":{"en":"Her eyes brightened.","cn":"她的眼睛亮了起来。"}},{"en":"to become or make something become more pleasant; to bring hope","cn":"（使）增添乐趣，有希望","g":"[transitive, intransitive]","ex":{"en":"A personal letter will usually brighten up a person's day.","cn":"一封私人来信往往就能使人一天心情愉快。"}},{"en":"to make something look more brightly coloured and attractive","cn":"使更艳丽；使更美丽","g":"[transitive]","ex":{"en":"Fresh flowers will brighten up any room in the house.","cn":"鲜花会使屋里的任何房间都亮丽生色。"}},{"en":"to improve and become brighter","cn":"放晴","g":"[intransitive]","ex":{"en":"According to the forecast, it should brighten up later.","cn":"根据天气预报，晚一点天应该会转晴。"}}]}},"briefing":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"情况介绍会；任务下达会","en":"A briefing is a meeting at which information or instructions are given to people, especially before they do something.","ex":{"en":"They're holding a press briefing tomorrow","cn":"他们明天将召开一个新闻发布会。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"information or instructions that you get before you have to do something 〔","cn":"行动前得到的〕情况简报，简要指示"}]},"vocab":{"pos":"n","senses":[{"en":"If you plan on going to the briefing at the White House, you'd better bring your audio recorder. These informational sessions can get very detailed, and you'll need to review the audio record."}]},"collocations":{"phrases":["ADJ. detailed, full, thorough | formal, informal | final She returned to Washington for a final briefing. | press","VERB + BRIEFING give sb All staff will be given a full briefing tomorrow. | get, receive | arrange, hold I asked him to arrange a formal bri","BRIEFING + NOUN session | document, paper","PREP. at a/the~ Details of the scheme will be announced at a press briefing later today. | ~ by/from a briefing by the commanding officer | "]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdebriefing.mp3","us":"media/ldoce/hwd/ame/2/briefing.mp3"},"examples":[{"en":"Captain Trent gave his men a full briefing.","cn":"特伦特队长给了他的部属详细的指示。"},{"en":"a briefing session/paper","cn":"任务发布会/文件"}],"oxford":{"phon":"ˈbriːfɪŋ","pos":"noun","senses":[{"en":"a meeting in which people are given instructions or information","cn":"传达指示会；情况介绍会","g":"[countable]","ex":{"en":"Details of the plan will be announced at a press briefing later today.","cn":"这项计划的详细情况将在今天晚些时候的新闻发布会上宣布。"}},{"en":"the detailed instructions or information that are given at such a meeting","cn":"详细指示；详情介绍","g":"[countable, uncountable]","lab":"especially in North American English","ex":{"en":"Captain Trent gave his men a full briefing.","cn":"特伦特队长给了他的下属详细的指示。"}}]},"base":"brief"},"brutality":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"野蛮行径；残暴行为","en":"Brutality is cruel and violent treatment or behaviour. A brutality is an instance of cruel and violent treatment or behaviour.","ex":{"en":"Her experience of men was of domination and brutality.","cn":"男人给她的感受是支配一切，野蛮残暴。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"fighting, killing, and other violent behaviour","cn":""},{"en":"angry feelings or behaviour that often results in fighting","cn":""},{"en":"deliberately cruel and violent behaviour that shows no pity for the person who is injured or killed","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Brutality is extreme cruelty, deliberate violent meanness. Avoid being the giver or receiver of brutality if you wish to remain a happy human."}]},"collocations":{"phrases":["ADJ. extreme, great | police There have been many complaints of police brutality.","QUANT. act This was an act of extreme brutality.","PREP. ~ against brutality against prisoners | ~ by brutality by the security forces | ~ to/towards brutality to others"]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41brutality.mp3","us":"media/ldoce/hwd/ame/6/ld41brutality.mp3"},"examples":[{"en":"police brutality","cn":"警察的粗暴"},{"en":"the brutalities of war","cn":"战争的残酷"}],"oxford":{"phon":"bruːˈtæləti","pos":"noun","senses":[{"en":"violent and cruel behaviour; the fact of being violent and cruel","cn":"暴力和残忍的行为或事实","g":"[uncountable]","ex":{"en":"police brutality","cn":"警察的暴行"}},{"en":"the fact of being direct and clear about something unpleasant, often because of not thinking of people's feelings","cn":"对不愉快的事情直截了当，通常是因为没有考虑人们的感受","g":"[uncountable]","ex":{"en":"the brutality of his words","cn":"他言语的残酷"}}]}},"bronchitis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"支气管炎","en":"Bronchitis is an illness like a very bad cough, in which your bronchial tubes become sore and infected.","ex":{"en":"He was in bed with bronchitis.","cn":"他患支气管炎卧病在床。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an illness that affects your bronchial tubes and makes you cough","cn":"支气管炎"}]},"media":{"uk":"media/ldoce/hwd/bre/4/bronchitis0205.mp3","us":"media/ldoce/hwd/ame/d/bronchitis.mp3"},"examples":[{"en":"He was suffering from chronic bronchitis.","cn":"他患有慢性支气管炎。"},{"en":"a bronchitic cough","cn":"支气管炎引起的咳嗽"}],"oxford":{"phon":"brɒŋˈkaɪtɪs","pos":"noun","senses":[{"en":"an illness that affects the bronchial tubes leading to the lungs","cn":"支气管炎","ex":{"en":"He was suffering from chronic bronchitis.","cn":"他患有慢性支气管炎。"}}]}},"breadth":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"宽度","en":"The breadth of something is the distance between its two sides.","ex":{"en":"The breadth of the whole camp was 400 paces.","cn":"整个营地的宽度为400步。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"广度；广泛性","en":"The breadth of something is its quality of consisting of or involving many different things.","ex":{"en":"Older people have a tremendous breadth of experience","cn":"年长者阅历相当丰富。"}},{"pos":"PHRASE 短语","cn":"到处；处处","en":"If you say that someone does something or something happens throughout or across the length and breadth of a place, you are emphasizing that it happens everywhere in that place.","ex":{"en":"The group built their reputation by playing across the length and breadth of North America","cn":"这个乐队通过到北美各地演出打响了知名度。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the distance from one side of something to the other","cn":"宽度﹐阔度"},{"en":"the quality of including a lot of different people, things, or ideas","cn":"广泛性﹐广度"}]},"vocab":{"pos":"n","senses":[{"en":"If you measure the distance of an object from side to side, you are measuring the object’s breadth : “Theodore measured the breadth of the table before buying it to make sure it would fit in his small kitchen.”"}]},"collocations":{"phrases":["PREP. in ~ The pool is 5 metres in breadth.","PHRASES the length and breadth of sth He travels the length and breadth of (= all over) the country. 2 great extent or variety","ADJ. full, great, sheer","PHRASES breadth of experience I need a greater breadth of experience. | breadth of interest/knowledge/understanding, breadth of mind, breadt"]},"media":{"uk":"media/ldoce/hwd/bre/7/breadth0205.mp3","us":"media/ldoce/hwd/ame/1/breadth.mp3"},"examples":[{"en":"a new political leader whose breadth of vision (= willingness to accept new ideas) can persuade others to change","cn":"一位凭远见卓识说服他人改变旧思想的新政治领袖"},{"en":"She estimated the breadth of the lake to be 500 metres.","cn":"她估计湖面大约有 500 米宽。"}],"oxford":{"phon":"bredθ","pos":"noun","senses":[{"en":"the distance or measurement from one side to the other; how broad or wide something is","cn":"宽度","ex":{"en":"She estimated the breadth of the lake to be 500 metres.","cn":"她估计湖面大约有 500 米宽。"}},{"en":"a wide range (of knowledge, interests, etc.)","cn":"（知识、兴趣等）广泛","ex":{"en":"He was surprised at her breadth of reading.","cn":"他对于她的博览群书感到惊讶。"}}]}},"bridesmaid":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女傧相；伴娘","en":"A bridesmaid is a woman or a girl who helps and accompanies a bride on her wedding day."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the woman who is getting married","cn":""},{"en":"the man who is getting married","cn":""},{"en":"a man and a woman who have just got married","cn":""}]},"collocations":{"phrases":["ADJ. chief","VERB + BRIDESMAID toast The bridegroom asked the guests to stand and then toasted the bridesmaids."]},"media":{"uk":"media/ldoce/hwd/bre/4/bridesmaid0205.mp3","us":"media/ldoce/hwd/ame/5/bridesmaid.mp3"},"oxford":{"phon":"ˈbraɪdzmeɪd","pos":"noun","senses":[{"en":"a young woman or girl who helps a bride before and during the marriage ceremony","cn":"女傧相；伴娘","ex":{"en":"Jo asked her sister to be (a) bridesmaid.","cn":"乔邀请她姐姐担任伴娘。"}}]}},"browser":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指用来在万维网上搜索信息的）浏览软件，浏览器","en":"A browser is a piece of computer software that you use to search for information on the Internet, especially on the World Wide Web."},{"pos":"N-COUNT 可数名词","cn":"逛商店的人","en":"A browser is someone who browses in a shop.","ex":{"en":"...a casual browser.","cn":"闲逛的人"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a network of computer connections that allows computer users around the world to exchange information","cn":""},{"en":"used to form words that relate to activities involving use of the Internet, especially those connected with business.","cn":""},{"en":"used to form words that relate to activities involving the use of computers, especially the Internet","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A browser is a looker: either a program that lets you surf the Internet or a person in a store who just looks around without buying."}]},"collocations":{"phrases":["ADJ. web | default What do you use as your default browser? | frames-capable, frames-enabled","VERB + BROWSER update, upgrade","BROWSER + VERB support frames","BROWSER + NOUN toolbar, window","PREP. on a/the ~ Click the &lsquo;back&rsquo; button on your browser. •"]},"media":{"uk":"media/ldoce/hwd/bre/8/browser0205.mp3","us":"media/ldoce/hwd/ame/7/laadbrowser.mp3"},"examples":[{"en":"a Web browser","cn":"互联网浏览器"}],"oxford":{"phon":"ˈbraʊzə(r)","pos":"noun","senses":[{"en":"a computer program that lets you look at or read documents on the World Wide Web","cn":"浏览器；浏览程序","ex":{"en":"What do you use as your default browser?","cn":"你用什么浏览器作为默认浏览器？"}},{"en":"a person who looks through books, magazines, etc. or at things for sale, but may not seriously intend to buy anything","cn":"浏览图书报刊者；逛商店的人","ex":{"en":"There were one or two browsers in the bookstore.","cn":"书店里有一两个浏览器。"}}]}},"brink":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"边缘","en":"If you are on the brink of something, usually something important, terrible, or exciting, you are just about to do it or experience it.","ex":{"en":"Their economy is teetering on the brink of collapse","cn":"他们的经济徘徊在崩溃的边缘。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"not completely or exactly, but almost - use this when the difference is not important","cn":""},{"en":"almost completely","cn":""},{"en":"not completely, but almost - use this to say that something has not happened, but that it almost has","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The brink of something is the very edge of it. If you want to give your mom a good scare, stand on the brink of a steep cliff and slowly lean forward."}]},"collocations":{"phrases":["ADJ. very","VERB + BRINK be (poised) on, hover on, stand on, teeter on Scientists are on the brink of making a major new discovery. animals hovering on ","PREP. ~ of the brink of bankruptcy/death/war"]},"media":{"uk":"media/ldoce/hwd/bre/a/brink0205.mp3","us":"media/ldoce/hwd/ame/a/brink.mp3"},"examples":[{"en":"Scientists are on the brink of making a major new discovery.","cn":"科学家很快就会有新的重大发现。"},{"en":"He's pulled the company back from the brink (= he has saved it from disaster).","cn":"他使公司起死回生。"}],"oxford":{"phon":"brɪŋk","pos":"noun","senses":[{"en":"if you are on the brink of something, you are almost in a very new, dangerous or exciting situation","cn":"（新的、危险的，或令人兴奋的处境的）边缘，初始状态","ex":{"en":"on the brink of collapse/war/death/disaster","cn":"濒于崩溃／战争／死亡／灾难"}},{"en":"the extreme edge of land, for example at the top of a cliff or by a river","cn":"（峭壁、河岸等的）边沿，边缘","lab":"literary","ex":{"en":"the brink of the precipice","cn":"悬崖边缘"}}]}},"brace":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使做好准备（面对不快的事或困难）","en":"If you brace yourself for something unpleasant or difficult, you prepare yourself for it.","ex":{"en":"He braced himself for the icy plunge into the black water","cn":"他做好了准备要跳进冰冷的脏水里。"}},{"pos":"VERB 动词","cn":"（为保持平衡或避免摔倒）使紧靠","en":"If you brace yourself against something or brace part of your body against it, you press against something in order to steady your body or to avoid falling.","ex":{"en":"Elaine braced herself against the dresser and looked in the mirror","cn":"伊莱恩紧贴着衣橱照镜子。"}},{"pos":"VERB 动词","cn":"绷紧（肩或膝）","en":"If you brace your shoulders or knees, you keep them stiffly in a particular position.","ex":{"en":"He braced his shoulders as the snow slashed across his face.","cn":"雪花如刀割般刮在他的脸上，他绷紧了双肩。"}},{"pos":"VERB 动词","cn":"支撑；加固","en":"To brace something means to strengthen or support it with something else.","ex":{"en":"Overhead, the lights showed the old timbers, used to brace the roof.","cn":"灯光照亮了头顶上支撑屋顶的旧房梁。"}},{"pos":"N-COUNT 可数名词","cn":"一对；一双","en":"You can refer to two things of the same kind as a brace of that thing. The plural form is also brace .","ex":{"en":"...a brace of bottles of Mercier Rose champagne.","cn":"两瓶玛喜尔玫瑰香槟"}},{"pos":"N-COUNT 可数名词","cn":"（用以加固或支撑身体某部位的）支架，托架","en":"A brace is a device attached to a part of a person's body, for example to a weak leg, in order to strengthen or support it.","ex":{"en":"He wore leg braces after polio in childhood","cn":"他幼时得过小儿麻痹症后双腿安上了支架。"}},{"pos":"N-COUNT 可数名词","cn":"牙齿矫正器；牙箍","en":"A brace is a metal device that can be fastened to a child's teeth in order to help them grow straight."},{"pos":"N-PLURAL 复数名词","cn":"（裤子的）背带，吊带","en":"Braces are a pair of straps that pass over your shoulders and fasten to your trousers at the front and back in order to stop them from falling down."},{"pos":"N-COUNT 可数名词","cn":"大括号","en":"Braces or curly braces are a pair of written marks that you place around words, numbers, or parts of a computer code, for example to indicate that they are connected in some way or are separate from other parts of the writing or code."}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make yourself mentally and physically ready for something that you will have to do","cn":""},{"en":"if you are prepared for something unpleasant or difficult, you expect it and you have thought about it, so that you can deal with it more easily","cn":""},{"en":"to do all the things you need to do in order to be ready to do something, especially things such as washing or dressing before you go somewhere","cn":""}]},"vocab":{"pos":"1 n v 2 n 3 n","senses":[{"en":"A brace is a support that helps to steady or strengthen, and to brace is to prepare for something hard. So brace yourself for that impromptu meeting with your boss if you haven't been performing well."}]},"collocations":{"phrases":["ADJ. leg, neck, shoulder","VERB + BRACE have, wear I used to wear a brace.","PREP. ~ on a brace on his teeth 2 braces: for holding trousers up","BRACE + VERB hold sth up, support sth The braces held up his trousers. •"]},"media":{"uk":"media/ldoce/hwd/bre/d/brace_v0205.mp3","us":"media/ldoce/hwd/ame/e/brace1.mp3"},"examples":[{"en":"He stood with his legs and shoulders braced, ready to lift the weights.","cn":"他绷紧腿和肩膀站着，准备举起杠铃。"},{"en":"UN troops are braced for more violence.","cn":"联合国部队准备应付更多的暴行。"}],"oxford":{"phon":"breɪs","pos":"noun","senses":[{"en":"a device that holds things together or holds and supports them in position","cn":"箍子；夹子；支架","g":"[countable]","ex":{"en":"a neck brace (= worn to support the neck after an injury)","cn":"矫治用的颈箍"}},{"en":"a metal device that people, especially children, wear inside the mouth to help their teeth grow straight","cn":"（儿童）牙箍","g":"[countable]","lab":"North American English","ex":{"en":"My daughter has to wear a brace on her teeth.","cn":"我的女儿得戴牙箍以矫正牙齿。"}},{"en":"long narrow pieces of cloth, leather, etc. for holding trousers up. They are fastened to the top of the trousers at the front and back and passed over the shoulders.","cn":"吊裤带；背带","g":"[plural]","lab":"British English","ex":{"en":"a pair of braces","cn":"一副吊裤带"}},{"en":"a metal support for weak or injured legs","cn":"双脚规形夹（支撑无力或受伤的腿的金属支架）","g":"[countable, usually plural]","lab":"North American English"},{"en":"either of the two marks, { }, used to show that the words, etc. between them are connected","cn":"大括弧；大括号","g":"[countable]"},{"en":"a pair of birds or animals that have been killed in hunting","cn":"猎获的一对鸟（或兽）","g":"[countable]","ex":{"en":"two brace of partridge(s)","cn":"两对山鹑。"}},{"en":"to prepare somebody/yourself for something difficult or unpleasant that is going to happen","cn":"（为困难或坏事）使做准备；使防备","ex":{"en":"UN troops are braced for more violence.","cn":"联合国部队准备应付更多的暴行。"},"pos":"verb"},{"en":"to press your body or part of your body strongly against something in order to stop yourself from falling","cn":"使（身体或身体部位）顶住，抵住（以免跌倒等）","ex":{"en":"They braced themselves against the wind.","cn":"他们顶着大风站稳。"},"pos":"verb"},{"en":"to contract the muscles in your body or part of your body before doing something that is physically difficult","cn":"（做费劲的事之前）绷紧肌肉","ex":{"en":"He stood with his legs and shoulders braced, ready to lift the weights.","cn":"他绷紧腿和肩膀站着，准备举起杠铃。"},"pos":"verb"},{"en":"to make something stronger or more solid by supporting it with something","cn":"加强；加固","lab":"specialist","ex":{"en":"The roof was braced by lengths of timber.","cn":"屋顶用几根木头支撑固定住了。"},"pos":"verb"}]}},"brisbane":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a port and the capital city of Queensland state in the east of Australia, the third largest city in the country","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/p028-000002641.mp3","us":"media/ldoce/hwd/ame/b/p028-000002641.mp3"},"oxford":{"phon":"ˈbrɪzbən","pos":"","senses":[{"en":"the capital city of Queensland, Australia, a port on the Brisbane River","cn":"布里斯班（澳大利亚昆士兰州首府，布里斯班河沿岸港口）"}]}},"brunt":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"承受主要压力；首当其冲","en":"To bear the brunt or take the brunt of something unpleasant means to suffer the main part or force of it.","ex":{"en":"Young people are bearing the brunt of unemployment","cn":"年轻人首当其冲，面临失业压力。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to receive the worst part of an attack, criticism, bad situation etc","cn":"受到最严厉的攻击[批评]﹔首当其冲"}]},"vocab":{"pos":"n","senses":[{"en":"If you are the oldest child, you might bear the brunt of your parents' anger, even if you are not the instigator of the misdeed. Brunt means the worst part of something."}]},"collocations":{"phrases":["ADJ. full, main","VERB + BRUNT bear, take The prime minister has taken the brunt of the criticism.","PREP. the ~ of"]},"media":{"uk":"media/ldoce/hwd/bre/b/brunt0205.mp3","us":"media/ldoce/hwd/ame/a/brunt.mp3"},"examples":[{"en":"Schools will bear the brunt of cuts in government spending.","cn":"政府削减开支，学校将首当其冲受到影响。"},{"en":"an industry that bore the brunt of the recession","cn":"经济衰退时受到冲击最大的行业"}]},"breakup":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（婚姻、关系或联系的）破裂，终结","en":"The break-up of a marriage, relationship, or association is the act of it finishing or coming to an end because the people involved decide that it is not working successfully.","ex":{"en":"Since the break-up of his marriage he had not formed any new relationships.","cn":"他婚姻破裂后没有谈新朋友。"}},{"pos":"N-COUNT 可数名词","cn":"（组织或国家的）分裂，解体","en":"The break-up of an organization or a country is the act of it separating or dividing into several parts.","ex":{"en":"...the break-up of British Rail for privatisation","cn":"在私有化过程中英国铁路公司的解体"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of ending a marriage or relationship 〔","cn":"婚姻或关系的〕破裂"},{"en":"the separation of a group, organization, or country into smaller parts","cn":"分裂﹔解散﹔解体"}]},"collocations":{"phrases":["ADJ. family, marital, marriage","VERB + BREAKUP lead to"]},"media":{"uk":"media/ldoce/hwd/bre/0/breakup0205.mp3","us":"media/ldoce/hwd/ame/a/breakup.mp3"},"examples":[{"en":"the breakup of the Soviet Union","cn":"苏联的解体"},{"en":"the breakup of her marriage","cn":"她婚姻的破裂"}]},"briefcase":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"公文包","en":"A briefcase is a case used for carrying documents in."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flat case used especially by business people for carrying papers or documents","cn":"公文包﹐公事包"}]},"collocations":{"phrases":["ADJ. battered He wore a torn suit and carried a battered briefcase. | bulging | executive | leather, plastic","VERB + BRIEFCASE open, snap open, unlock | close, lock, shut, snap shut | carry, hold, pick up | drop, put down","BRIEFCASE + VERB be bulging with sth, be full of sth, be stuffed with sth, contain sth"]},"media":{"img":["media/ldoce/img/briefcase.jpg","media/thumb/briefcase.jpg"],"uk":"media/ldoce/hwd/bre/2/briefcase0205.mp3","us":"media/ldoce/hwd/ame/1/briefcase.mp3"},"oxford":{"phon":"ˈbriːfkeɪs","pos":"noun","senses":[{"en":"a flat case used for carrying papers and documents","cn":"公文包；公事包","ex":{"en":"He wore a torn suit and carried a battered briefcase.","cn":"他穿一身破西服，提着一个破旧不堪的公文包。"}}]}},"break-in":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"强行闯入","en":"If there has been a break-in, someone has got into a building by force.","ex":{"en":"The break-in had occurred just before midnight.","cn":"这次非法闯入就发生在午夜前。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the crime of stealing money or other things from a bank, shop etc, especially by using threats or violence","cn":""},{"en":"the crime of stealing something, especially when the person they are stolen from is not present","cn":""},{"en":"the crime of entering a house or other building illegally and stealing things","cn":""}]},"collocations":{"phrases":["ADJ. attempted | factory, house, etc. BREAK-IN + NOUN happen, take place","PREP. ~ at a break-in at the factory"]},"media":{"uk":"media/ldoce/hwd/bre/2/break_in0205.mp3","us":"media/ldoce/hwd/ame/f/break-in.mp3"},"examples":[{"en":"Since the break-in we’ve had all our locks changed.","cn":"自从发生入室盗窃案后﹐我们更换了所有的锁。"}],"oxford":{"phon":"ˈbreɪk ɪn","pos":"noun","senses":[{"en":"an entry into a building using force, usually to steal something","cn":"破门而入；闯入；入室偷窃","ex":{"en":"Police were called to three break-ins in the same area last night.","cn":"昨夜警方接到同一地区的三宗入室盗窃的报案。"}}]}},"brooch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胸针；领针；饰针","en":"A brooch is a small piece of jewellery which has a pin at the back so it can be fastened on a dress, blouse, or coat."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of jewellery that you fasten to your clothes, usually worn by women","cn":"胸针；领针；饰针"}]},"vocab":{"pos":"n v","senses":[{"en":"That fancy pin your Grandma used to wear on her blouse or lapel? It's a brooch , held in place by a sharp needle clasp."}]},"collocations":{"phrases":["ADJ. cameo | diamond, pearl, etc.","VERB + BROOCH have on, wear | pin She pinned a large amethyst brooch to her lapel."]},"media":{"img":["media/ldoce/img/brooch.jpg","media/thumb/brooch.jpg"],"uk":"media/ldoce/hwd/bre/8/brooch0205.mp3","us":"media/ldoce/hwd/ame/b/brooch.mp3"},"oxford":{"phon":"brəʊtʃ","pos":"noun","senses":[{"en":"a piece of jewellery with a pin on the back of it, that can be fastened to your clothes","cn":"饰针；胸针；领针","ex":{"en":"She pinned a large amethyst brooch to her lapel.","cn":"她在翻领上别了一枚大大的紫水晶饰针。"}}]}},"brothel":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"妓院","en":"A brothel is a building where men can go to pay to have sex with prostitutes."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a house where men pay to have sex with prostitute s","cn":"妓院"}]},"collocations":{"phrases":["VERB + BROTHEL go to, visit He used to visit a brothel in Paris. | run She ran a brothel in Soho.","BROTHEL + NOUN keeper","PREP. in a/the ~ She works in a brothel in Brighton."]},"media":{"uk":"media/ldoce/hwd/bre/5/brothel0205.mp3","us":"media/ldoce/hwd/ame/4/brothel.mp3"},"oxford":{"phon":"ˈbrɒθl","pos":"noun","senses":[{"en":"a house where people go to have sex in exchange for money","cn":"妓院","ex":{"en":"He used to visit a brothel in Paris.","cn":"他以前常到巴黎的一家妓院。"}}]}},"brawl":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"打架；斗殴","en":"A brawl is a rough or violent fight.","ex":{"en":"He had been in a drunken street brawl.","cn":"他参与了一场酒后街头斗殴。"}},{"pos":"V-RECIP 相互动词","cn":"打架；斗殴","en":"If someone brawls, they fight in a very rough or violent way.","ex":{"en":"He was suspended for a year from University after brawling with police over a speeding ticket","cn":"他为了一张超速罚单与警察厮打，被大学勒令停学1年。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which people hit or attack each other because of an argument, or as a sport","cn":""},{"en":"a fight between opposing armies or groups of people","cn":""},{"en":"a short fight that is not very violent","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"A bar fight is a brawl . A fight in the cafeteria which turns into a free-for-all can also be called a brawl . A brawl is a noisy fight in a crowd."}]},"collocations":{"phrases":["ADJ. drunken | bar-room, pub, street | mass","VERB + BRAWL provoke, spark, start | be/become/get involved in, be/get caught up in, get into","PREP. in a/the ~ They got caught up in a street brawl. | ~ between a brawl between different gangs of football supporters. | ~ over a brawl "]},"media":{"uk":"media/ldoce/hwd/bre/0/brawl_n0205.mp3","us":"media/ldoce/hwd/ame/e/brawl.mp3"},"examples":[{"en":"They were arrested for brawling in the street.","cn":"他们因在街上打斗而遭到拘捕。"},{"en":"a drunken brawl","cn":"酒后闹事"}],"oxford":{"phon":"brɔːl","pos":"noun","senses":[{"en":"a noisy and violent fight involving a group of people, usually in a public place","cn":"喧闹；斗殴；闹事","ex":{"en":"He got into a drunken brawl in a bar.","cn":"他在酒吧喝醉酒后发生争吵。"}},{"en":"to take part in a noisy and violent fight, usually in a public place","cn":"打斗；闹事","ex":{"en":"They were arrested for brawling in the street.","cn":"他们因在街上打斗而遭到拘捕。"},"pos":"verb"}]}},"breach":{"collins":{"senses":[{"pos":"VERB 动词","cn":"违反，破坏（条约、法律或承诺）","en":"If you breach an agreement, a law, or a promise, you break it.","ex":{"en":"The newspaper breached the code of conduct on privacy","cn":"该报违反了保护隐私的行为准则。"}},{"pos":"N-VAR 可变名词","cn":"（对条约、法律或承诺的）违反，破坏","en":"A breach of an agreement, a law, or a promise is an act of breaking it.","ex":{"en":"The congressman was accused of a breach of secrecy rules.","cn":"这位议员被控违反了保密规定。"}},{"pos":"N-COUNT 可数名词","cn":"（关系的）裂痕，破裂","en":"A breach in a relationship is a serious disagreement which often results in the relationship ending.","ex":{"en":"Their actions threatened a serious breach in relations between the two countries.","cn":"他们的行动使两国关系面临严重恶化的危险。"}},{"pos":"VERB 动词","cn":"突破；攻破；给…造成缺口","en":"If someone or something breaches a barrier, they make an opening in it, usually leaving it weakened or destroyed.","ex":{"en":"The limestone is sufficiently fissured for tree roots to have breached the roof of the cave","cn":"石灰岩上有许多缝隙，故而树根能从岩洞顶部长出来。"}},{"pos":"VERB 动词","cn":"突破，攻破（防卫）","en":"If you breach someone's security or their defences, you manage to get through and attack an area that is heavily guarded and protected.","ex":{"en":"The bomber had breached security by hurling his dynamite from a roof overlooking the building.","cn":"这名爆炸手从一个俯瞰这座大楼的楼顶上投下炸药，破坏了安保系统。"}},{"pos":"PHRASE 短语","cn":"临时代替；临时顶替","en":"If you step into the breach, you do a job or task which someone else was supposed to do or has done in the past, because they are suddenly unable to do it.","ex":{"en":"I was persuaded to step into the breach temporarily when they became too ill to continue.","cn":"在他们病得很重无法坚持的情况下，我被劝服去临时顶替他们。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an illegal action for which you can be punished","cn":""},{"en":"an illegal action, especially one that breaks a law that protects someone's rights","cn":""},{"en":"an action that breaks a law or agreement, especially one that has been agreed by several different countries - use this about a serious illegal action","cn":""}]},"vocab":{"pos":"1 n v 2 n v","senses":[{"en":"A breach is a violation of a law, duty, or promise. If you'd contracted to mow your neighbor's lawn and don't do it, he can sue you for breach of contract. Or he can mow the lawn himself."}]},"collocations":{"phrases":["ADJ. clear, fundamental, grave, serious | deliberate, flagrant He refused to bow to the Queen, in deliberate breach of etiquette. | minor | ","VERB + BREACH constitute Such behaviour constitutes a breach of confidentiality. | commit","PREP. in ~ of The court's decision is in breach of the European Convention on human rights. | ~ of a minor breach of discipline","PHRASES a breach of confidence/trust, a breach of confidentiality/contract He was sued for breach of contract. | a breach of security, a bre","VERB + BREACH cause, lead to | heal, repair","PREP. ~ between What caused the breach between the two brothers? | ~ with She left home following the breach with her family."]},"media":{"uk":"media/ldoce/hwd/bre/d/breach_n0205.mp3","us":"media/ldoce/hwd/ame/3/breach1.mp3"},"examples":[{"en":"They escaped through a breach in the wire fence.","cn":"他们从铁丝网上的一个缺口逃走了。"},{"en":"They are in breach of Article 119.","cn":"他们违犯了第 119 条。"}],"oxford":{"phon":"briːtʃ","pos":"noun","senses":[{"en":"a failure to do something that must be done by law","cn":"（对法规等的）违背，违犯","g":"[countable, uncountable]","lab":"British English","ex":{"en":"a breach of contract/copyright/warranty","cn":"违约；侵犯版权；违反保证"}},{"en":"an action that breaks an agreement to behave in a particular way","cn":"破坏；辜负","g":"[countable, uncountable]","ex":{"en":"a breach of confidence/trust","cn":"泄密；背信"}},{"en":"a break in a relationship between people or countries","cn":"（关系）中断，终止","g":"[countable]","ex":{"en":"The disagreement caused a serious breach in Franco-German relations.","cn":"这一分歧导致法德关系严重破裂。"}},{"en":"an opening that is created during a military attack or by strong winds or seas","cn":"突破口；缺口；窟窿","g":"[countable]","ex":{"en":"They escaped through a breach in the wire fence.","cn":"他们从铁丝网上的一个缺口逃走了。"}},{"en":"to not keep to an agreement or not keep a promise","cn":"违反；违背","ex":{"en":"The government is accused of breaching the terms of the treaty.","cn":"政府被控违反条约中的规定。"},"pos":"verb"},{"en":"to make a hole in a wall, fence, etc. so that somebody/something can go through it","cn":"在…上打开缺口","ex":{"en":"The dam had been breached.","cn":"大坝决口了。"},"pos":"verb"}]}},"breathtaking":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人兴奋的；激动人心的；壮观的","en":"If you say that something is breathtaking, you are emphasizing that it is extremely beautiful or amazing.","ex":{"en":"The house has breathtaking views from every room","cn":"这所房子的每个房间都能看到令人惊叹的美景。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used to describe something that looks, feels, sounds etc so good that it gives you a lot of pleasure","cn":""},{"en":"used when saying that something looks, feels, or sounds very nice","cn":""},{"en":"pleasant to look at – often used about things that are not big or impressive","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. absolutely, quite, truly"]},"media":{"uk":"media/ldoce/hwd/bre/4/breathtaking0205.mp3","us":"media/ldoce/hwd/ame/1/breathtaking.mp3"},"examples":[{"en":"He spoke with breathtaking arrogance.","cn":"他说话时的傲慢态度令人咋舌。"},{"en":"The scene was one of breathtaking beauty.","cn":"美妙的景色令人叹为观止。"}],"oxford":{"phon":"ˈbreθteɪkɪŋ","pos":"adjective","senses":[{"en":"very exciting or impressive (usually in a pleasant way)","cn":"激动人心的；令人赞叹的","ex":{"en":"a breathtaking view of the mountains","cn":"群山的壮丽景色"}},{"en":"very surprising","cn":"惊人的","ex":{"en":"He spoke with breathtaking arrogance.","cn":"他说话时的傲慢态度令人咋舌。"}}]}},"breaststroke":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"蛙泳","en":"Breaststroke is a swimming stroke which you do lying on your front, moving your arms and legs horizontally in a circular motion."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of swimming in which you push your arms out and then bring them back in a circle towards you while bending your knees towards your body and then kicking out","cn":"蛙泳"}]},"media":{"uk":"media/ldoce/hwd/bre/7/breaststroke0205.mp3","us":"media/ldoce/hwd/ame/4/breaststroke.mp3","img":["media/thumb/breaststroke.jpg"]},"oxford":{"phon":"ˈbreststrəʊk","pos":"noun","senses":[{"en":"a style of swimming that you do on your front, moving your arms and legs away from your body and then back towards it in a circle","cn":"蛙泳","ex":{"en":"to swim breaststroke","cn":"蛙泳"}}]}},"breathless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"上气不接下气的；呼吸困难的；气喘吁吁的","en":"If you are breathless, you have difficulty in breathing properly, for example because you have been running or because you are afraid or excited.","ex":{"en":"I was a little breathless and my heartbeat was bumpy and fast","cn":"我有点儿喘不上气，心脏咚咚地快速跳动着。"}},{"pos":"ADJ 形容词","cn":"令人喘不过气的","en":"You use breathless for emphasis when you are describing feelings of excitement or exciting situations.","ex":{"en":"Technology has advanced at a breathless pace.","cn":"技术进步速度惊人，日新月异。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unable to breathe easily, especially because you are unhealthy","cn":""},{"en":"having difficulty breathing, especially because you have just been running, climbing stairs etc","cn":""},{"en":"to breathe very quickly and deeply because you are having difficulty breathing normally, for example after running fast or because you have been injured","cn":""}]},"collocations":{"phrases":["VERBS be, feel, seem, sound | become | leave sb, make sb The unaccustomed exercise left him breathless.","ADV. very | a little, quite, rather, slightly, somewhat He felt quite breathless. | suddenly","PREP. with By the end of the walk, she was breathless with exertion. The children peered through the open door, breathless with excitement."]},"media":{"uk":"media/ldoce/hwd/bre/e/breathless0205.mp3","us":"media/ldoce/hwd/ame/4/breathless.mp3"},"examples":[{"en":"They maintained a breathless (= very fast) pace for half an hour.","cn":"他们用疾速的步伐走了半小时。"},{"en":"the breathless excitement of seeing each other again","cn":"再次相互见面时令人无比的兴奋"}],"oxford":{"phon":"ˈbreθləs","pos":"adjective","senses":[{"en":"having difficulty in breathing; making it difficult for somebody to breathe","cn":"（使）气喘吁吁的，上气不接下气的","ex":{"en":"He arrived breathless at the top of the stairs.","cn":"他爬上楼梯顶时气喘吁吁的。"}},{"en":"experiencing, or making somebody experience, a strong emotional reaction","cn":"（使人）屏息的，目瞪口呆的","lab":"formal","ex":{"en":"the breathless excitement of seeing each other again","cn":"再次相见时无比的兴奋"}},{"en":"with no air or wind","cn":"令人窒息的；无风的","lab":"formal","ex":{"en":"the breathless heat of a summer afternoon","cn":"夏日午后的闷热"}}]}}});
